export const gradeE4RikaBQuestions: Question[] = [
  {"id": "grade_e4_rika_b001", "subject": "rika", "question": "ものをくらべる実験（じっけん）をするとき、くらべたいこと以外（いがい）は、どうしますか。", "answer": "同じにする", "hint": "ちがいが出た理由（りゆう）を、ひとつにしぼるためだよ。", "explanation": "【何を聞かれているか】くらべたいこと以外（いがい）の、決（き）め方。\n\n【なぜそうなるのか】いくつものことを同時に変（か）えると、結果（けっか）がちがったとき、どれのせいなのか分からなくなるから。くらべたいことだけを変えて、ほかは同じにすれば、ちがいの理由（りゆう）がひとつに決まる。\n\n【ステップ1】くらべたいことを1つ決める\n【ステップ2】それ以外（水の量（りょう）・置（お）く場所（ところ）・時間など）は、ぜんぶ同じにそろえる\n【ステップ3】ちがいが出たら、くらべたいことのせいだと分かる\n\n【答え】同じにする\n\n【たしかめ】「変えたのは1つだけか」と、実験（じっけん）の計画を見直す。\n\n【よくあるまちがい】水の量や置く場所まで、いっしょに変えてしまう。くらべたいこと以外は、同じにする。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["ぜんぶ変える", "同じにする", "どうでもよい"]},
  {"id": "grade_e4_rika_b002", "subject": "rika", "question": "品物（しなもの）ごとの数の大きさを、ぼうの高さでくらべるグラフを何といいますか。ひらがなとカタカナで書きましょう。", "answer": "ぼうグラフ", "hint": "数が大きいほど、ぼうが高くなるグラフだよ。", "explanation": "【何を聞かれているか】ぼうの高さで数をくらべるグラフの名前。\n\n【なぜそうなるのか】数の大きさを目で見てくらべたいときは、ぼうの高さにすると、どれが多いか一目で分かるから。このグラフを、ぼうグラフという。\n\n【ステップ1】グラフのかたちを思いうかべる\n【ステップ2】ぼうが何本もならび、高さで数をあらわす\n【ステップ3】その名前は「ぼうグラフ」\n\n【答え】ぼうグラフ\n\n【たしかめ】一番高いぼうが、一番数が多いものになっているか、グラフを見てたしかめる。\n\n【よくあるまちがい】時間といっしょに変（か）わるようすを見るグラフ（折（お）れ線（せん）グラフ）と、まちがえてしまう。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b003", "subject": "rika", "question": "時間がたつにつれて、気温（きおん）が変（か）わっていくようすを見るのに、あうグラフはどれですか。", "answer": "折れ線グラフ", "hint": "点を線でつないで、ふえたりへったりするようすを見るよ。", "explanation": "【何を聞かれているか】気温（きおん）の変（か）わり方を見るグラフ。\n\n【なぜそうなるのか】時間といっしょに変わっていくものは、点を線でつなぐと、上がったり下がったりするようすが、ひと目で分かるから。この線のグラフを折（お）れ線（せん）グラフといい、気温の変わり方を見るのに使（つか）う。\n\n【ステップ1】気温は時間とともに変わっていく\n【ステップ2】時間ごとの気温に点をうち、線でつなぐ\n【ステップ3】線の向（む）きで、上がり下がりが分かる折れ線グラフになる\n\n【答え】折れ線グラフ\n\n【たしかめ】線が右上がりのところは気温が上がっていて、右下がりのところは下がっていると見られるか。\n\n【よくあるまちがい】ぼうグラフにしてしまう。ぼうグラフは数の大きさをくらべるためのもので、変わり方を見るには折れ線グラフ。", "difficulty": "standard", "examType": "chugaku", "grade": "e4", "choices": ["折れ線グラフ", "ぼうグラフ", "グラフはいらない"]},
  {"id": "grade_e4_rika_b004", "subject": "rika", "question": "折（お）れ線（せん）グラフで、線が右上がりになっているところでは、数は、ふえていますか、へっていますか。「ふえている」か「へっている」のどちらかを、ひらがなで書きましょう。", "answer": "ふえている", "hint": "右へ行くほど、点の位置（いち）が高くなっているよ。", "explanation": "【何を聞かれているか】右上がりの線が表（あらわ）す変（か）わり方。\n\n【なぜそうなるのか】折（お）れ線（せん）グラフでは、右へ行くほど時間が進（すす）む。点の位置（いち）が高くなっているということは、数が大きくなっているということだから、右上がりの線は「ふえている」ことを表す。\n\n【ステップ1】グラフの右へ行くほど、時間が進む\n【ステップ2】右上がりは、点が高くなっていく\n【ステップ3】高くなる＝数がふえている\n\n【答え】ふえている\n\n【たしかめ】右下がりの線なら反対（はんたい）に「へっている」になるか、考えてたしかめる。\n\n【よくあるまちがい】右上がりを「へっている」と読んでしまう。点が高いほど数が大きい。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b005", "subject": "rika", "question": "9時の気温（きおん）は14℃、12時の気温は21℃でした。9時から12時までに、気温は何℃上がりましたか。数字で書きましょう。", "answer": "7", "hint": "大きいほうの数から、小さいほうの数を引こう。", "explanation": "【何を聞かれているか】気温（きおん）が上がった分。\n\n【なぜそうなるのか】表（ひょう）にならべた数は、あとの数からはじめの数を引くと、上がった分が分かるから。上がった分は「ちがい」なので、引き算で出す。\n\n【ステップ1】9時は14℃、12時は21℃\n【ステップ2】上がった分は、21から14を引く\n【ステップ3】21−14＝7\n\n【答え】7\n\n【たしかめ】14に7をたすと21になるか、たし算でたしかめる。\n\n【よくあるまちがい】21−14のかわりに、21と14をたして35としてしまう。ちがいを聞かれたら、引き算。", "difficulty": "standard", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b006", "subject": "rika", "question": "温度計（おんどけい）のえきの先が、15のめもりから4めもり上にありました。1めもりが1℃のとき、何℃ですか。数字で書きましょう。", "answer": "19", "hint": "15から、上へ1めもりずつ数えていくよ。", "explanation": "【何を聞かれているか】温度計（おんどけい）の読み取（と）り。\n\n【なぜそうなるのか】温度計は、えきの先がどのめもりにあるかを読む。1めもりが1℃なので、15のめもりから上へ4めもり進（すす）んだ数が、そのときの温度になるから。\n\n【ステップ1】15のめもりが、スタートの目じるし\n【ステップ2】上に4めもりなので、15に4をたす\n【ステップ3】15＋4＝19\n\n【答え】19\n\n【たしかめ】19のめもりから下へ4めもり数えて、15にもどるか、たしかめる。\n\n【よくあるまちがい】4めもりを4℃ではなく、そのまま4と答えてしまう。15から数えはじめた数を答える。", "difficulty": "standard", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b007", "subject": "rika", "question": "実験（じっけん）をする前に、「たぶん、こうなる」と、わけをつけて考えておくことを、何といいますか。ひらがなで書きましょう。", "answer": "よそう", "hint": "あとで、実（じっ）さいの結果（けっか）と見くらべるよ。", "explanation": "【何を聞かれているか】実験（じっけん）の前に考えておくことの名前。\n\n【なぜそうなるのか】先に「こうなるはず」と考えておくと、実験の結果（けっか）と見くらべられて、どこがちがったかを考えられる。このとき、わけもいっしょに考えておくと、よりよく分かる。\n\n【ステップ1】実験の前に、結果を考える\n【ステップ2】考えたことに、わけをつける\n【ステップ3】この考えを「よそう」という\n\n【答え】よそう\n\n【たしかめ】「実験のあとに考えたこと」は、よそうではなく、ふり返（かえ）りや感想（かんそう）になることをたしかめる。\n\n【よくあるまちがい】よそうがはずれたら、書きなおしてしまう。よそうは、そのままのこしておく。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b008", "subject": "rika", "question": "同じ実験（じっけん）を、何度（ど）もくり返（かえ）してみるのは、何をたしかめるためですか。", "answer": "結果がいつも同じになるか", "hint": "1回だけの結果（けっか）は、たまたまかもしれないよ。", "explanation": "【何を聞かれているか】くり返（かえ）す理由（りゆう）。\n\n【なぜそうなるのか】1回だけの結果（けっか）は、まちがいや、たまたまかもしれない。何度（ど）も同じ実験（じっけん）をして、同じ結果が出れば、その結果はたしかだと言えるから。\n\n【ステップ1】1回では、たまたまかもしれない\n【ステップ2】同じ実験を、もう一度、ていねいにやる\n【ステップ3】同じ結果が出れば、たしかだと分かる\n\n【答え】結果がいつも同じになるか\n\n【たしかめ】3回やって、どれも同じ結果だったかを、記録（きろく）を見てたしかめる。\n\n【よくあるまちがい】1回やって、結果が出たら、それで十分だと思ってしまう。たしかめるには、くり返す。", "difficulty": "standard", "examType": "chugaku", "grade": "e4", "choices": ["よそうを変えるため", "道具の名前をおぼえるため", "結果がいつも同じになるか"]},
  {"id": "grade_e4_rika_b009", "subject": "rika", "question": "かんさつや実験（じっけん）で見たことを、あとで見直せるように書きとめたものを、何といいますか。ひらがなで書きましょう。", "answer": "きろく", "hint": "かんさつカードや、実験（じっけん）の表（ひょう）も、これにあたるよ。", "explanation": "【何を聞かれているか】書きとめたものの名前。\n\n【なぜそうなるのか】かんさつや実験（じっけん）で見たことは、書いておかないと、あとでわすれてしまう。書きとめておけば、あとで表（ひょう）やグラフにして、くらべたり、考えたりできるから。\n\n【ステップ1】見たことを、すぐに書きとめる\n【ステップ2】日づけ・場所（ところ）・数なども書く\n【ステップ3】書きとめたものを「きろく」という\n\n【答え】きろく\n\n【たしかめ】きろくを見て、いつ・どこで・何を見たかが分かるかどうか、読み直す。\n\n【よくあるまちがい】思ったことだけを書いて、見たことや数を書かない。きろくは、見たとおりに書く。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b010", "subject": "rika", "question": "春になって、あたたかくなってくると、冬のあいだ土の中ですごしていたカエルは、どうなりますか。", "answer": "土の中から出てきて、動きはじめる", "hint": "気温（きおん）が上がると、動物（どうぶつ）は活発（はつ）になるよ。", "explanation": "【何を聞かれているか】春のカエルのようす。\n\n【なぜそうなるのか】冬の間は、気温（きおん）がひくいので、カエルは土の中でじっとしている。春になって気温が上がると、体があたたまって、動（うご）けるようになり、土の中から出てくるから。\n\n【ステップ1】冬は、気温がひくくて、じっとしている\n【ステップ2】春は、気温が上がって、動けるようになる\n【ステップ3】カエルは土の中から出てくる\n\n【答え】土の中から出てきて、動きはじめる\n\n【たしかめ】「あたたかくなると、動物（どうぶつ）が動きはじめる」という春のようすと、合っているかをたしかめる。\n\n【よくあるまちがい】「冬のままずっとねている」と答えてしまう。春は気温が上がって、動きはじめる。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["ずっと土の中で、ねている", "土の中から出てきて、動きはじめる", "水の中でこおってしまう"]},
  {"id": "grade_e4_rika_b011", "subject": "rika", "question": "春にさく、黄色い花で、わた毛のあるたねをつくる草は何ですか。カタカナで書きましょう。", "answer": "タンポポ", "hint": "道ばたや野原で見られる、黄色い花だよ。", "explanation": "【何を聞かれているか】春にさく黄色い花の草。\n\n【なぜそうなるのか】タンポポは、春にあたたかくなると、黄色い花をさかせる。花がおわると、わた毛のついたたねができて、風にのって遠くへ飛（と）んでいくから。\n\n【ステップ1】春の野原の花を思い出す\n【ステップ2】黄色い花で、わた毛のたねをつくる\n【ステップ3】それはタンポポ\n\n【答え】タンポポ\n\n【たしかめ】春の野原で、タンポポをさがして、花とわた毛のたねを見くらべてみる。\n\n【よくあるまちがい】夏の花のヒマワリと、まちがえてしまう。ヒマワリは夏にさく大きな花。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b012", "subject": "rika", "question": "4月のはじめの気温（きおん）は11℃、4月の終（お）わりの気温は19℃でした。気温は何℃上がりましたか。数字で書きましょう。", "answer": "8", "hint": "終（お）わりの気温（きおん）から、はじめの気温を引こう。", "explanation": "【何を聞かれているか】4月の間に上がった気温（きおん）。\n\n【なぜそうなるのか】春は、日がたつにつれて、だんだん気温が上がっていく。上がった分は、あとの気温からはじめの気温を引くと分かるから。\n\n【ステップ1】はじめは11℃、終（お）わりは19℃\n【ステップ2】上がった分は、19から11を引く\n【ステップ3】19−11＝8\n\n【答え】8\n\n【たしかめ】11に8をたすと19になるか、たしかめる。\n\n【よくあるまちがい】19と11をたして30としてしまう。上がった分は、ちがいなので引き算。", "difficulty": "standard", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b013", "subject": "rika", "question": "花にあつまるチョウやミツバチは、花から何をとっていますか。ひらがなで書きましょう。", "answer": "みつ", "hint": "あまい、えきのことだよ。", "explanation": "【何を聞かれているか】花から虫がとっているもの。\n\n【なぜそうなるのか】花のおくには、あまいみつがたまっている。チョウやミツバチは、そのみつをすいに花へやってくる。そのとき、体に花のこな（かふん）がつくから、虫がいろいろな花を行き来して、たねができやすくなる。\n\n【ステップ1】花にあつまる虫を思い出す\n【ステップ2】虫は花の中に口をのばす\n【ステップ3】とっているのは、あまいみつ\n\n【答え】みつ\n\n【たしかめ】花のおくをのぞいて、虫が口をのばす場所（ところ）と、みつの出る場所が同じか考える。\n\n【よくあるまちがい】「花びら」や「葉（は）」を食べていると考えてしまう。虫がとっているのは、みつ。", "difficulty": "standard", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b014", "subject": "rika", "question": "ヘチマのくきは、のびるとき、まわりのものにからみつくために、何を出しますか。ひらがなで書きましょう。", "answer": "まきひげ", "hint": "らせんのように、くるくるとまいた、細い糸のようなものだよ。", "explanation": "【何を聞かれているか】ヘチマがからみつくためのもの。\n\n【なぜそうなるのか】ヘチマは、くきがやわらかく、自分では立ちつづけられないつる草。そこで、まきひげという細いものをのばして、まわりのぼうやあみにからみついて、上へのびていくから。\n\n【ステップ1】ヘチマはつる草で、自分では立てない\n【ステップ2】ささえになるものに、細いものでからみつく\n【ステップ3】そのしくみを、まきひげという\n\n【答え】まきひげ\n\n【たしかめ】ヘチマを育（そだ）てるとき、あみやぼうを立てると、まきひげがからみつくかをかんさつする。\n\n【よくあるまちがい】「根（ね）」でからみついていると考えてしまう。からみつくのは、くきから出るまきひげ。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b015", "subject": "rika", "question": "春になると、「ホーホケキョ」と鳴く鳥は何ですか。カタカナで書きましょう。", "answer": "ウグイス", "hint": "春の山や林で、よく聞こえる、きれいな声だよ。", "explanation": "【何を聞かれているか】春に「ホーホケキョ」と鳴く鳥。\n\n【なぜそうなるのか】春は、気温（きおん）が上がって、鳥たちが元気になり、よく鳴くきせつ。「ホーホケキョ」と鳴くのは、ウグイスで、春をつげる鳥ともいわれているから。\n\n【ステップ1】春に鳴く鳥を思い出す\n【ステップ2】「ホーホケキョ」という鳴き声に注（ちゅう）目する\n【ステップ3】その鳥はウグイス\n\n【答え】ウグイス\n\n【たしかめ】ほかの鳥（スズメ・カラス）の鳴き声とくらべて、ちがいをたしかめる。\n\n【よくあるまちがい】ツバメやスズメと、まちがえてしまう。「ホーホケキョ」はウグイス。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b016", "subject": "rika", "question": "かんさつカードに、天気といっしょに書く、空気のあたたかさを、ひらがなで何といいますか。ひらがなで書きましょう。", "answer": "きおん", "hint": "温度計（おんどけい）ではかる、空気のあたたかさだよ。", "explanation": "【何を聞かれているか】かんさつカードに書く、空気の温度（おんど）。\n\n【なぜそうなるのか】生き物（いきもの）のようすは、あたたかさによって変（か）わる。そこで、かんさつカードには、天気といっしょに、空気の温度である「気温」を書いておくと、あとで生き物のようすとくらべられるから。\n\n【ステップ1】生き物は、あたたかさで変わる\n【ステップ2】あたたかさを、温度計ではかる\n【ステップ3】空気の温度を「きおん」という\n\n【答え】きおん\n\n【たしかめ】日づけ・天気・気温がそろっているか、カードを見直してたしかめる。\n\n【よくあるまちがい】「水の温度（水温）」や「地面（じめん）の温度」と、ごちゃごちゃにしてしまう。空気は気温。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b017", "subject": "rika", "question": "春になって、あたたかくなると、野原の草のせたけは、どうなっていきますか。", "answer": "のびていく", "hint": "あたたかさと日光で、草は元気に育（そだ）つよ。", "explanation": "【何を聞かれているか】春の草のせたけの変（か）わり方。\n\n【なぜそうなるのか】草は、あたたかくなると、土の中の水をすいあげて、日光を受（う）けて育（そだ）つ。そのため、春には、どんどんせたけがのびていくから。\n\n【ステップ1】春は、気温（きおん）が上がる\n【ステップ2】草は、水と日光で育つ\n【ステップ3】せたけがのびていく\n\n【答え】のびていく\n\n【たしかめ】同じ草のせたけを、1週間ごとにはかって、のびているか、記録（きろく）をくらべる。\n\n【よくあるまちがい】「冬と同じで変わらない」と考えてしまう。春はあたたかくなり、草は育つ。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["ひくくなっていく", "ずっと変わらない", "のびていく"]},
  {"id": "grade_e4_rika_b018", "subject": "rika", "question": "キャベツ畑（はたけ）に飛（と）んできて、白いはねを持（も）つ、春のチョウは何ですか。カタカナで書きましょう。", "answer": "モンシロチョウ", "hint": "名前に「白」が入っているチョウだよ。", "explanation": "【何を聞かれているか】春に見られる白いチョウ。\n\n【なぜそうなるのか】モンシロチョウは、はねが白く、はねにある小さな黒いもんがとくちょう。春になると、キャベツなどの葉（は）に、たまごをうみにやってくるから。\n\n【ステップ1】白いはねのチョウを思い出す\n【ステップ2】名前の中にも「白」が入っている\n【ステップ3】モンシロチョウ\n\n【答え】モンシロチョウ\n\n【たしかめ】キャベツ畑（はたけ）で、白いチョウを見つけて、はねの黒いもんを見くらべる。\n\n【よくあるまちがい】黄色いチョウ（キチョウ）と、まちがえてしまう。白いのがモンシロチョウ。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b019", "subject": "rika", "question": "ヘチマの花で、花のもとに、ふくらんだ部（ぶ）分があるのは、おばなですか、めばなですか。ひらがなで書きましょう。", "answer": "めばな", "hint": "実（み）になる部（ぶ）分が、花のもとにあるほうだよ。", "explanation": "【何を聞かれているか】花のもとがふくらんだ花。\n\n【なぜそうなるのか】ヘチマには、おばなとめばながあり、めばなだけが、花のもとに、実（み）になるふくらみを持（も）っている。花がおわると、そのふくらみが大きくなって、実になるから。\n\n【ステップ1】ヘチマの花を2つ見くらべる\n【ステップ2】ふくらんだ部（ぶ）分のある花をさがす\n【ステップ3】ふくらみがあるのは、めばな\n\n【答え】めばな\n\n【たしかめ】花がおわったあと、ふくらみが実になるかを、ヘチマでかんさつしてたしかめる。\n\n【よくあるまちがい】おばなに、実がなると思ってしまう。実ができるのは、めばな。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b020", "subject": "rika", "question": "セミのよう虫が、せい虫になるときに、ぬぎすてる皮（かわ）を何といいますか。ひらがなで書きましょう。", "answer": "ぬけがら", "hint": "夏、木のみきなどに、のこっているよ。", "explanation": "【何を聞かれているか】セミがぬぎすてた皮（かわ）の名前。\n\n【なぜそうなるのか】セミのよう虫は、土の中から出てきて、木にのぼり、せなかをわって、成虫（せいちゅう）になる。成虫になるときにぬぎすてた皮を、ぬけがらというから。\n\n【ステップ1】よう虫が土の中から出て、木にのぼる\n【ステップ2】皮をぬいで、成虫になる\n【ステップ3】ぬぎすてた皮が、ぬけがら\n\n【答え】ぬけがら\n\n【たしかめ】夏の木のみきで、ぬけがらを見つけて、せなかがわれているかをたしかめる。\n\n【よくあるまちがい】「よう虫」と、まちがえてしまう。ぬけがらは、中身（なかみ）のない、ぬぎすてた皮。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b021", "subject": "rika", "question": "夏に鳴くセミは、おすとめすの、どちらが鳴きますか。", "answer": "おす", "hint": "めすをよぶために鳴くよ。", "explanation": "【何を聞かれているか】鳴くセミは、おすかめすか。\n\n【なぜそうなるのか】セミは、おすが鳴いて、めすをよんでいる。おすのはらの中には、音を出すしくみがあるが、めすにはそれがほとんど無（な）いから。\n\n【ステップ1】夏にセミが鳴く\n【ステップ2】鳴いているのは、めすをよぶため\n【ステップ3】鳴くのはおす\n\n【答え】おす\n\n【たしかめ】セミを手にとって、はらをよく見ると、おすだけに音を出すところがあることが分かる。\n\n【よくあるまちがい】「めすも同じように鳴く」と思ってしまう。セミは、おすが鳴く。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["おす", "めす", "どちらも鳴く"]},
  {"id": "grade_e4_rika_b022", "subject": "rika", "question": "ヘチマのくきの長さは、6月は70cm、7月は180cmでした。6月から7月にかけて、何cmのびましたか。数字で書きましょう。", "answer": "110", "hint": "7月の長さから、6月の長さを引こう。", "explanation": "【何を聞かれているか】ヘチマがのびた分。\n\n【なぜそうなるのか】夏は気温（きおん）が高いので、ヘチマは大きく育（そだ）つ。のびた分は、あとの長さから、はじめの長さを引いて出すから。\n\n【ステップ1】6月は70cm、7月は180cm\n【ステップ2】のびた分は、180から70を引く\n【ステップ3】180−70＝110\n\n【答え】110\n\n【たしかめ】70に110をたすと180になるか、たしかめる。\n\n【よくあるまちがい】180cmをそのまま答えにしてしまう。聞かれているのは、のびた分。", "difficulty": "standard", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b023", "subject": "rika", "question": "夏に大きな黄色い花をさかせる草は、どれですか。", "answer": "ヒマワリ", "hint": "夏の花だんで、せが高く育（そだ）つよ。", "explanation": "【何を聞かれているか】夏にさく花。\n\n【なぜそうなるのか】ヒマワリは、夏の日光をたくさん受（う）けて、せが高くなり、大きな黄色い花をさかせる。サクラとウメは、春やその少し前にさく木だから。\n\n【ステップ1】夏にさく花を思い出す\n【ステップ2】サクラとウメは、春ごろにさく\n【ステップ3】夏にさくのはヒマワリ\n\n【答え】ヒマワリ\n\n【たしかめ】夏の花だんで、ヒマワリがさいているかを、かんさつしてたしかめる。\n\n【よくあるまちがい】サクラを夏の花だと思ってしまう。サクラは、春にさく木。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["サクラ", "ウメ", "ヒマワリ"]},
  {"id": "grade_e4_rika_b024", "subject": "rika", "question": "夏のはじめ、ツバメの親は、巣（す）のひなに何を運（はこ）んできますか。漢字（かんじ）一字で書きましょう。", "answer": "虫", "hint": "ひなは、体を大きくするために、これを食べるよ。", "explanation": "【何を聞かれているか】ツバメのひなのえさ。\n\n【なぜそうなるのか】ツバメの親は、空を飛（と）びながら、虫をつかまえて、巣（す）にいるひなに運（はこ）ぶ。ひなは、虫を食べて、大きく育（そだ）つから。\n\n【ステップ1】夏のはじめは、ツバメの子育てのきせつ\n【ステップ2】親は、空で小さな生き物（いきもの）をつかまえる\n【ステップ3】運ぶものは、虫\n\n【答え】虫\n\n【たしかめ】巣の下で、親が何度（ど）も巣に出入りして、えさを運んでいるのを見て、たしかめる。\n\n【よくあるまちがい】木の実（み）や、草のたねだと思ってしまう。ツバメのひなは、虫を食べる。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b025", "subject": "rika", "question": "カブトムシのせい虫が、夏によく集（あつ）まるのは、どんな所（ところ）ですか。", "answer": "木のしるが出る、木のみき", "hint": "カブトムシは、あまいものがすきだよ。", "explanation": "【何を聞かれているか】カブトムシが集（あつ）まる場所（ところ）。\n\n【なぜそうなるのか】カブトムシは、木のしるをなめて生きている。しるが出ている木のみきには、あまいにおいがするので、夏の夜によく集まるから。\n\n【ステップ1】カブトムシは、何を食べるかを考える\n【ステップ2】木のしるをなめて生きている\n【ステップ3】木のしるが出る、木のみきにいる\n\n【答え】木のしるが出る、木のみき\n\n【たしかめ】夏の夜、クヌギなどの木のみきに、カブトムシが集まっているか、見てたしかめる。\n\n【よくあるまちがい】水の中や、地面（じめん）にいると思ってしまう。木のしるが出るみきに集まる。", "difficulty": "standard", "examType": "chugaku", "grade": "e4", "choices": ["つめたい水の中", "木のしるが出る、木のみき", "日かげの地面"]},
  {"id": "grade_e4_rika_b026", "subject": "rika", "question": "ヘチマのくきが、いちばんよくのびるのは、春・夏・秋のうち、どの季節（きせつ）ですか。漢字（かんじ）一字で書きましょう。", "answer": "夏", "hint": "気温（きおん）が高くて、日光がたくさんある季節（きせつ）だよ。", "explanation": "【何を聞かれているか】ヘチマがよくのびる季節（きせつ）。\n\n【なぜそうなるのか】ヘチマは、あたたかさと日光で大きく育（そだ）つ。気温（きおん）が高く、日光が強い夏に、1か月で1m以（い）上のびることもあるから。\n\n【ステップ1】ヘチマの育ち方は、気温と日光できまる\n【ステップ2】一番気温が高いのは、夏\n【ステップ3】よくのびるのは夏\n\n【答え】夏\n\n【たしかめ】1か月ごとののびをグラフにして、夏のところが急（きゅう）に上がっているか見る。\n\n【よくあるまちがい】春にまいたばかりのころが一番のびると思ってしまう。春は、まだのびの小さい時期（じき）。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b027", "subject": "rika", "question": "夏のある日、日なたの気温（きおん）は36℃、日かげの気温は30℃でした。日なたは日かげより、何℃高いですか。数字で書きましょう。", "answer": "6", "hint": "大きいほうから、小さいほうを引こう。", "explanation": "【何を聞かれているか】日なたと日かげの気温（きおん）のちがい。\n\n【なぜそうなるのか】日なたでは日光が直せつ当たるので、日かげより気温が高くなる。ちがいは、高いほうから低（ひく）いほうを引いて出すから。\n\n【ステップ1】日なたは36℃、日かげは30℃\n【ステップ2】ちがいは、36から30を引く\n【ステップ3】36−30＝6\n\n【答え】6\n\n【たしかめ】30に6をたすと36になるか、たしかめる。\n\n【よくあるまちがい】36と30をたして66としてしまう。ちがいは、引き算。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b028", "subject": "rika", "question": "ハクチョウは、冬のあいだ、どこから日本にわたってきますか。", "answer": "北のさむい国", "hint": "ハクチョウは、冬になると、日本のみずうみにやってくるよ。", "explanation": "【何を聞かれているか】ハクチョウがわたってくる方向（ほうこう）。\n\n【なぜそうなるのか】ハクチョウは、夏のあいだ北の国ですごし、秋から冬にかけて、さむくなる前に、日本のみずうみへわたってくる。春になると、また北へ帰っていくから。\n\n【ステップ1】ハクチョウは、わたり鳥\n【ステップ2】冬は、北の国のほうがとてもさむくなる\n【ステップ3】北の国から、日本へやってくる\n\n【答え】北のさむい国\n\n【たしかめ】「ツバメは春に南から来る」ことと、見くらべて、どちらが冬に来る鳥かをたしかめる。\n\n【よくあるまちがい】「南からくる」と、ツバメとまちがえる。ハクチョウは北から来て、冬を日本ですごす。", "difficulty": "standard", "examType": "chugaku", "grade": "e4", "choices": ["南のあたたかい国", "北のさむい国", "日本の海の中"]},
  {"id": "grade_e4_rika_b029", "subject": "rika", "question": "秋に、野原で鳴く虫は、どれですか。", "answer": "スズムシ", "hint": "夜、草むらから、すずしげな音が聞こえるよ。", "explanation": "【何を聞かれているか】秋に鳴く虫。\n\n【なぜそうなるのか】スズムシは、秋の夜に、草むらでおすが鳴く虫。セミとカブトムシは、夏に見られる虫で、秋にはほとんど見かけなくなるから。\n\n【ステップ1】秋の夜に鳴く虫を思い出す\n【ステップ2】セミとカブトムシは、夏の虫\n【ステップ3】秋に鳴くのは、スズムシ\n\n【答え】スズムシ\n\n【たしかめ】秋の夜に、草むらで鳴き声を聞いて、虫の名前をたしかめる。\n\n【よくあるまちがい】セミを秋の虫だと思ってしまう。セミは、夏の終（お）わりごろまで。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["セミ", "カブトムシ", "スズムシ"]},
  {"id": "grade_e4_rika_b030", "subject": "rika", "question": "サクラの葉（は）は、秋になると、色が変（か）わって、やがて地面（じめん）にちります。ちった葉を何といいますか。ひらがなで書きましょう。", "answer": "おちば", "hint": "地面（じめん）に積（つ）もった葉（は）のことだよ。", "explanation": "【何を聞かれているか】ちった葉（は）の名前。\n\n【なぜそうなるのか】秋になって気温（きおん）が下がると、サクラの葉は、赤や黄色に色が変（か）わって、えだからはなれて落（お）ちる。地面（じめん）に落ちた葉をおちばという。\n\n【ステップ1】秋は、気温が下がる\n【ステップ2】気温が下がると、サクラの葉の色が変わる\n【ステップ3】地面に落ちた葉が、おちば\n\n【答え】おちば\n\n【たしかめ】落ち葉を拾（ひろ）って、赤や黄色にそまっているか、見てたしかめる。\n\n【よくあるまちがい】「かれ草」と、いってしまう。木から落ちた葉は、おちば。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b031", "subject": "rika", "question": "秋になってかれたヘチマの実（み）から取（と）り出して、次（つぎ）の春に土にまくものは何ですか。ひらがなで書きましょう。", "answer": "たね", "hint": "実（み）をふると、カラカラと音がするよ。", "explanation": "【何を聞かれているか】次（つぎ）の春にまくもの。\n\n【なぜそうなるのか】ヘチマは、花がおわったあとに実（み）ができ、その中にたねをつくる。実がかれると、中のたねを取（と）り出して、次の春にまくと、また芽（め）が出るから。\n\n【ステップ1】実の中をわって見る\n【ステップ2】黒くて平（たい）たいものがたくさん入っている\n【ステップ3】それは、たね\n\n【答え】たね\n\n【たしかめ】かれた実をふると、中でカラカラと音がする。わって、中身（なかみ）をたしかめる。\n\n【よくあるまちがい】「め」や「花」が入っていると考えてしまう。実の中には、たねが入っている。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b032", "subject": "rika", "question": "サクラの木の冬のえだにあって、春に花や葉（は）になる、小さなかたまりを何といいますか。ひらがなで書きましょう。", "answer": "ふゆめ", "hint": "冬のあいだに、えだの先に見られる、小さなつぶだよ。", "explanation": "【何を聞かれているか】冬にサクラのえだについているもの。\n\n【なぜそうなるのか】サクラは、冬に葉（は）を落（お）とすが、えだには小さな芽（め）がついている。この芽は、冬をこして、春になると、花や葉にそだつから、冬芽という。\n\n【ステップ1】冬のサクラのえだを見る\n【ステップ2】えだの先に、小さな芽がついている\n【ステップ3】冬の芽だから「ふゆめ」\n\n【答え】ふゆめ\n\n【たしかめ】同じえだを、冬と春にくらべて、芽が花や葉に変（か）わっているかをたしかめる。\n\n【よくあるまちがい】「つぼみ」だと思ってしまう。つぼみは、花になる前の部（ぶ）分で、冬芽は、冬をこす芽のこと。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b033", "subject": "rika", "question": "冬のあいだ、土の中などで、じっと動（うご）かずにすごすことを何といいますか。ひらがなで書きましょう。", "answer": "とうみん", "hint": "カエルやヘビが、冬にすることだよ。", "explanation": "【何を聞かれているか】冬に動（うご）かないですごすこと。\n\n【なぜそうなるのか】冬は、気温（きおん）がひくくて、食べものもとぼしい。カエルやヘビなどは、土の中などで、ほとんど動かずに冬をこす。これをとうみんという。\n\n【ステップ1】冬は、気温がひくい\n【ステップ2】食べ物（もの）が少なく、動くと、体の力を使（つか）ってしまう\n【ステップ3】動かずにすごすことを、とうみんという\n\n【答え】とうみん\n\n【たしかめ】春になって気温が上がると、とうみんをしていた動物が動きはじめるか、たしかめる。\n\n【よくあるまちがい】「ひっこし」と、まちがえてしまう。とうみんは、場所（ところ）を変（か）えず、じっとすること。", "difficulty": "standard", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b034", "subject": "rika", "question": "カブトムシは、冬のあいだ、どのすがたで土の中ですごしますか。", "answer": "よう虫", "hint": "夏に生まれた子どもの時期（じき）だよ。", "explanation": "【何を聞かれているか】カブトムシの冬のすがた。\n\n【なぜそうなるのか】カブトムシは、夏にたまごをうみ、たまごからかえったよう虫が、土の中で落（お）ち葉（ば）などを食べて大きくなる。そのまま冬をこして、春から初夏（しょか）にさなぎになり、夏にせい虫になるから。\n\n【ステップ1】夏にうまれたたまごから、よう虫がかえる\n【ステップ2】よう虫は、土の中で冬をこす\n【ステップ3】冬のすがたは、よう虫\n\n【答え】よう虫\n\n【たしかめ】冬に、落ち葉の下の土をほると、よう虫が出てくるか、図かんなどで調（しら）べる。\n\n【よくあるまちがい】せい虫のまま冬をこすと考えてしまう。カブトムシのせい虫は、冬の前にいなくなる。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["せい虫", "よう虫", "さなぎ"]},
  {"id": "grade_e4_rika_b035", "subject": "rika", "question": "10月の気温（きおん）は18℃、12月の気温は6℃でした。12月は10月より、何℃ひくいですか。数字で書きましょう。", "answer": "12", "hint": "大きいほうから、小さいほうを引こう。", "explanation": "【何を聞かれているか】10月と12月の気温（きおん）のちがい。\n\n【なぜそうなるのか】秋から冬にかけて、気温は少しずつ下がる。ちがいは、高いほうから低（ひく）いほうを引くと分かるから。\n\n【ステップ1】10月は18℃、12月は6℃\n【ステップ2】ちがいは、18から6を引く\n【ステップ3】18−6＝12\n\n【答え】12\n\n【たしかめ】6に12をたすと18になるか、たしかめる。\n\n【よくあるまちがい】18と6をたして24としてしまう。ちがいは、引き算。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b036", "subject": "rika", "question": "ヘチマのたね60こを、同じ数ずつ、6つのふくろに分けました。1つのふくろには、何こ入りますか。数字で書きましょう。", "answer": "10", "hint": "60を6つに分けるので、わり算だよ。", "explanation": "【何を聞かれているか】1ふくろ分のたねの数。\n\n【なぜそうなるのか】同じ数ずつ分けるときは、わり算で、1つ分の数が分かるから。60こを6つのふくろに分けるので、60÷6になる。\n\n【ステップ1】全部（ぜんぶ）で60こ\n【ステップ2】ふくろは6つ\n【ステップ3】60÷6＝10\n\n【答え】10\n\n【たしかめ】10こずつ6ふくろで、10×6＝60になるか、かけ算でたしかめる。\n\n【よくあるまちがい】60−6＝54と、引き算にしてしまう。同じ数ずつ分けるときは、わり算。", "difficulty": "standard", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b037", "subject": "rika", "question": "気温（きおん）をはかるとき、温度計（おんどけい）に直せつ当たらないようにするものは何ですか。漢字（かんじ）二字で書きましょう。", "answer": "日光", "hint": "空から来る、あたたかい光だよ。", "explanation": "【何を聞かれているか】温度計（おんどけい）に当ててはいけないもの。\n\n【なぜそうなるのか】温度計に日光が直せつ当たると、温度計そのものがあたたまって、空気の温度よりも高い数をしめしてしまう。空気の温度（気温）をはかるときは、日かげではかるから。\n\n【ステップ1】気温は、空気の温度\n【ステップ2】温度計に日光が当たると、温度計だけがあたたまる\n【ステップ3】日光が当たらない所（ところ）ではかる\n\n【答え】日光\n\n【たしかめ】日なたと日かげで、同じ温度計の数が同じかをくらべて、ちがいをたしかめる。\n\n【よくあるまちがい】日なたの方が、本当の気温だと考えてしまう。気温は、日光を当てずにはかる。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b038", "subject": "rika", "question": "百葉箱（ひゃくようばこ）のとびらは、日光が中に入らないように、どの方位（ほうい）に向（む）けますか。", "answer": "北", "hint": "日本では、一日のうち日光が少ししか当たらない方位（ほうい）だよ。", "explanation": "【何を聞かれているか】百葉箱（ひゃくようばこ）のとびらの向（む）き。\n\n【なぜそうなるのか】百葉箱は、中の温度計（おんどけい）に日光が当たらないように作る。日本では、太陽（たいよう）は南を通るので、とびらを北に向ければ、開（あ）けたときにも、日光が入りにくいから。\n\n【ステップ1】百葉箱の中には、温度計が入っている\n【ステップ2】日光は、南の方から強く当たる\n【ステップ3】反対（はんたい）の北に向ける\n\n【答え】北\n\n【たしかめ】百葉箱の前で、方位（ほうい）じしんを使（つか）って、とびらが北に向いているかをたしかめる。\n\n【よくあるまちがい】「南向き」だと思ってしまう。南向きだと、日光が中に入ってしまう。", "difficulty": "standard", "examType": "chugaku", "grade": "e4", "choices": ["南", "東", "北"]},
  {"id": "grade_e4_rika_b039", "subject": "rika", "question": "百葉箱（ひゃくようばこ）は、日光をはね返（かえ）して、中の温度（おんど）が上がりすぎないように、何色にぬってありますか。漢字（かんじ）一字で書きましょう。", "answer": "白", "hint": "雪や、くもの色と同じ色だよ。", "explanation": "【何を聞かれているか】百葉箱（ひゃくようばこ）の色。\n\n【なぜそうなるのか】白い色は、日光をよくはね返（かえ）して、あたたまりにくい。そのため、百葉箱を白くぬっておくと、箱の中が日光であたためられにくく、本当の気温（きおん）に近いかたちではかれるから。\n\n【ステップ1】百葉箱の中の温度計（おんどけい）は、日光であたたまるとこまる\n【ステップ2】白は、日光をよくはね返す\n【ステップ3】白くぬる\n\n【答え】白\n\n【たしかめ】黒い箱と白い箱を日なたに置（お）いて、さわってみて、どちらがあたたまっているか見くらべる。\n\n【よくあるまちがい】黒い色のほうが目立つから、と考えてしまう。目立つかどうかではなく、あたたまりにくい色にする。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b040", "subject": "rika", "question": "空全体（ぜんたい）の広さを10として、雲の量（りょう）が5のときの天気は、どれですか。", "answer": "晴れ", "hint": "雲の量（りょう）が8までなら、同じ天気になるよ。", "explanation": "【何を聞かれているか】雲の量（りょう）が5のときの天気。\n\n【なぜそうなるのか】天気は、空全体（ぜんたい）に対（たい）する雲の量で決（き）める。雲の量が0から8までは「晴れ」、9と10は「くもり」と決められているので、5は晴れになるから。\n\n【ステップ1】空全体を10としたときの、雲の量を見る\n【ステップ2】0から8までは、晴れ\n【ステップ3】5は晴れの中に入る\n\n【答え】晴れ\n\n【たしかめ】雲の量が9か10のときだけ、くもりになることを思い出して、たしかめる。\n\n【よくあるまちがい】半分も雲があるから「くもり」だと思ってしまう。くもりは、9と10のとき。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["くもり", "晴れ", "雨"]},
  {"id": "grade_e4_rika_b041", "subject": "rika", "question": "晴れた日に、1日のうちで、気温（きおん）がいちばんひくくなるのは、朝・昼・夕方のどれですか。漢字（かんじ）一字で書きましょう。", "answer": "朝", "hint": "夜のあいだに、地面（じめん）や空気が冷（ひ）えたあとだよ。", "explanation": "【何を聞かれているか】1日のうちで気温（きおん）が一番ひくい時こく。\n\n【なぜそうなるのか】夜は日光が当たらないので、地面（じめん）や空気が少しずつ冷（ひ）える。そして、朝、日がのぼるころに、もっともひくくなる。そのあと、日光が当たりはじめると、気温が上がっていくから。\n\n【ステップ1】夜は、日光が当たらず冷える\n【ステップ2】夜が明けるころが、冷えきったとき\n【ステップ3】一番ひくいのは、朝\n\n【答え】朝\n\n【たしかめ】晴れの日の気温を、1時間ごとにはかって、いちばんひくい時こくを見つける。\n\n【よくあるまちがい】夜の12時が一番ひくいと思ってしまう。夜のあいだ、冷えつづけるので、朝が一番ひくい。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b042", "subject": "rika", "question": "晴れた日、午後2時ごろから夜にかけて、気温（きおん）はどうなりますか。", "answer": "下がっていく", "hint": "日光が弱くなって、地面（じめん）や空気が冷（ひ）えていくよ。", "explanation": "【何を聞かれているか】午後2時から夜への気温（きおん）の変（か）わり方。\n\n【なぜそうなるのか】午後2時ごろ、気温が一番高くなったあと、太陽（たいよう）がしずんで日光が弱くなると、地面（じめん）も空気も冷（ひ）えていく。そのため、夜に向（む）けて、気温は下がっていくから。\n\n【ステップ1】午後2時ごろが、一番高い\n【ステップ2】そのあと、日光が弱くなる\n【ステップ3】気温は下がっていく\n\n【答え】下がっていく\n\n【たしかめ】1日の気温の折（お）れ線（せん）グラフで、午後2時のあとが右下がりになっているか、見る。\n\n【よくあるまちがい】夕方になっても、気温が上がりつづけると考えてしまう。気温が上がるのは、昼すぎまで。", "difficulty": "standard", "examType": "chugaku", "grade": "e4", "choices": ["下がっていく", "上がっていく", "ずっと変わらない"]},
  {"id": "grade_e4_rika_b043", "subject": "rika", "question": "ある晴れた日、最高（さいこう）気温（きおん）は28℃、最低（さいてい）気温は17℃でした。この日の気温のちがいは、何℃ですか。数字で書きましょう。", "answer": "11", "hint": "最高（さいこう）から、最低（さいてい）を引こう。", "explanation": "【何を聞かれているか】最高（さいこう）と最低（さいてい）の気温（きおん）のちがい。\n\n【なぜそうなるのか】1日の気温の変（か）わり方の大きさは、最高気温から最低気温を引いた数で分かる。晴れの日は、この差（さ）が大きくなりやすい。\n\n【ステップ1】最高は28℃、最低は17℃\n【ステップ2】ちがいは、28から17を引く\n【ステップ3】28−17＝11\n\n【答え】11\n\n【たしかめ】17に11をたすと28になるか、たし算でたしかめる。\n\n【よくあるまちがい】28と17をたして45としてしまう。ちがいを聞かれたら、引き算。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b044", "subject": "rika", "question": "温度計（おんどけい）の下のほうにある、赤いえきがたまった、丸い部（ぶ）分を何といいますか。ひらがなで書きましょう。", "answer": "えきだめ", "hint": "温度（おんど）が上がると、ここのえきがふくらんで、上へのぼっていくよ。", "explanation": "【何を聞かれているか】温度計（おんどけい）の下のふくらんだ部（ぶ）分の名前。\n\n【なぜそうなるのか】温度計の下にある丸い部分に、赤いえきがたまっている。温度が上がると、このえきがふくらんで上へのぼり、温度が下がると、へって下がる。この部分を、えきだめという。\n\n【ステップ1】温度計の形を思い出す\n【ステップ2】下のほうに、丸くふくらんだ部分がある\n【ステップ3】その名前は、えきだめ\n\n【答え】えきだめ\n\n【たしかめ】温度計を手で少しにぎると、えきだめがあたたまって、えきが上がるかたしかめる。\n\n【よくあるまちがい】温度計の上のほうだと思ってしまう。えきだめは、下にある。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b045", "subject": "rika", "question": "雨がふると、地面（じめん）を流（なが）れる水は、どこへ向（む）かって流れますか。", "answer": "低い所", "hint": "水は、ボールがころがるのと同じ向（む）きに動（うご）くよ。", "explanation": "【何を聞かれているか】水が流（なが）れる方向（ほうこう）。\n\n【なぜそうなるのか】水は、地面（じめん）のかたむきにしたがって、高い所（ところ）から低（ひく）い所へ流れる。ボールが坂道（さかみち）をころがるのと同じで、重（おも）さがあるので、下へ向かうから。\n\n【ステップ1】雨がふると、水は地面をつたう\n【ステップ2】地面には、高い所と低い所がある\n【ステップ3】水は、低い所へ流れる\n\n【答え】低い所\n\n【たしかめ】校庭（こうてい）に水をまいて、水の流れていく方向が、低い所に向かっているか見る。\n\n【よくあるまちがい】「高い所へ向かう」と、考えてしまう。水は、高い所から低い所へ流れる。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["低い所", "高い所", "平らな所だけ"]},
  {"id": "grade_e4_rika_b046", "subject": "rika", "question": "すなとどろでは、水がしみこみやすいのは、どちらですか。ひらがなで書きましょう。", "answer": "すな", "hint": "つぶが大きいほうが、すきまも大きいよ。", "explanation": "【何を聞かれているか】水がしみこみやすいもの。\n\n【なぜそうなるのか】すなは、どろにくらべて、つぶが大きく、つぶとつぶの間に大きなすきまがあるので、水が通りぬけやすい。どろは、つぶがとても小さく、すきまもせまいので、水が通りにくいから。\n\n【ステップ1】すなとどろの、つぶの大きさをくらべる\n【ステップ2】つぶが大きいと、すきまも大きい\n【ステップ3】水がしみこみやすいのは、すな\n\n【答え】すな\n\n【たしかめ】同じ量（りょう）の水を、すなとどろに注（ちゅう）いで、どちらが先にしみこむかを調（しら）べる。\n\n【よくあるまちがい】どろのほうが、水をすうと思ってしまう。つぶが小さいどろは、水がしみこみにくい。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b047", "subject": "rika", "question": "土のつぶが大きいほど、水がしみこむ速（はや）さは、どうなりますか。", "answer": "はやくなる", "hint": "つぶが大きいほど、つぶの間のすきまも大きくなるよ。", "explanation": "【何を聞かれているか】つぶの大きさと、しみこむ速（はや）さ。\n\n【なぜそうなるのか】土のつぶが大きいと、つぶとつぶの間のすきまが大きくなり、水がすきまを通りやすくなる。そのため、しみこむ速さが、はやくなるから。\n\n【ステップ1】つぶの大きさと、すきまの大きさは、つながっている\n【ステップ2】すきまが大きいと、水が通りやすい\n【ステップ3】しみこむ速さが、はやくなる\n\n【答え】はやくなる\n\n【たしかめ】つぶの大きさがちがう土で、しみこむ速さをくらべて、同じ結果（けっか）になるか調（しら）べる。\n\n【よくあるまちがい】つぶが大きいと、水がたまりやすくなって、おそくなると考えてしまう。大きいと、すきまが大きく、はやい。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["おそくなる", "変わらない", "はやくなる"]},
  {"id": "grade_e4_rika_b048", "subject": "rika", "question": "同じ量（りょう）の水を、すなとどろにそそぐと、すなは2分で、どろは5分でしみこみました。しみこむ時間は、何分ちがいますか。数字で書きましょう。", "answer": "3", "hint": "長い時間から、みじかい時間を引こう。", "explanation": "【何を聞かれているか】しみこむ時間のちがい。\n\n【なぜそうなるのか】すなは、水がしみこみやすいので、時間がみじかい。どろは、しみこみにくいので、時間が長い。ちがいは、長いほうからみじかいほうを引いて出すから。\n\n【ステップ1】すなは2分、どろは5分\n【ステップ2】ちがいは、5から2を引く\n【ステップ3】5−2＝3\n\n【答え】3\n\n【たしかめ】2に3をたすと5になるか、たしかめる。\n\n【よくあるまちがい】2と5をたして7としてしまう。ちがいは、引き算。", "difficulty": "standard", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b049", "subject": "rika", "question": "地面（じめん）のしめった土が、日なたでかわいていくとき、水が空気中へ出ていくことを何といいますか。ひらがなで書きましょう。", "answer": "じょうはつ", "hint": "せんたくものがかわくのも、同じ理由（りゆう）だよ。", "explanation": "【何を聞かれているか】水が空気中に出ていくこと。\n\n【なぜそうなるのか】日光や風で、地面（じめん）の水があたためられると、すがたの見えない気体になって、空気中へ出ていく。そのために土がかわく。この変化（へんか）を、じょう発（はつ）という。\n\n【ステップ1】土の水は、日光であたためられる\n【ステップ2】水が、すがたの見えない気体になる\n【ステップ3】この変化を「じょう発」という\n\n【答え】じょうはつ\n\n【たしかめ】水にぬらしたタオルを日なたと日かげにほして、どちらが早くかわくかをくらべる。\n\n【よくあるまちがい】「水がきえてなくなる」と考えてしまう。水は、空気中へ出ていっただけで、なくなってはいない。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b050", "subject": "rika", "question": "水が気体になったものを、何といいますか。ひらがなで書きましょう。", "answer": "すいじょうき", "hint": "空気中にあり、ふつうは目に見えないよ。", "explanation": "【何を聞かれているか】水の気体の名前。\n\n【なぜそうなるのか】水は、あたためられると、目に見えない気体にすがたを変（か）えて、空気中へ出ていく。この水の気体を、水じょう気という。空気の中には、いつも、少しの水じょう気がまじっているから。\n\n【ステップ1】水には、3つのすがたがある\n【ステップ2】氷（こおり）（固体（こたい））・水（えき体）・水の気体\n【ステップ3】水の気体の名前が、すいじょうき\n\n【答え】すいじょうき\n\n【たしかめ】「見えない」ことと、「湯気（ゆげ）（水のつぶ）」とのちがいを、ふりかえってたしかめる。\n\n【よくあるまちがい】「湯気」と、まちがえてしまう。湯気は、水じょう気が冷（ひ）えて小さな水のつぶになったもの。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b051", "subject": "rika", "question": "冷（つめ）たい水を入れたコップの、外側（がわ）に、水てきがつくのは、なぜですか。", "answer": "空気中の水じょう気が冷えて、水になったから", "hint": "コップのまわりの空気に、水がまじっているよ。", "explanation": "【何を聞かれているか】水てきがつく理由（りゆう）。\n\n【なぜそうなるのか】空気の中には、水じょう気がまじっている。冷（つめ）たいコップにふれた空気が冷やされると、水じょう気が水のつぶにもどって、コップの外側（がわ）につくから。コップの中の水は、ガラスを通りぬけない。\n\n【ステップ1】空気中には、水じょう気がある\n【ステップ2】コップにふれた空気が冷やされる\n【ステップ3】水じょう気が、水にもどってつく\n\n【答え】空気中の水じょう気が冷えて、水になったから\n\n【たしかめ】氷（こおり）を入れたコップと、入れないコップで、水てきのつき方をくらべる。\n\n【よくあるまちがい】中の水が、ガラスからしみ出したと考えてしまう。ガラスは水を通さない。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["空気中の水じょう気が冷えて、水になったから", "コップの中の水が、しみ出したから", "コップの外側がとけたから"]},
  {"id": "grade_e4_rika_b052", "subject": "rika", "question": "雨がふると、地面（じめん）を流（なが）れた水は、あつまって川になります。川の水は、さいごにどこへ流れこみますか。漢字（かんじ）一字で書きましょう。", "answer": "海", "hint": "日本のまわりに、広がっている水の広場だよ。", "explanation": "【何を聞かれているか】川の水がたどりつく所（ところ）。\n\n【なぜそうなるのか】水は、高い所から低（ひく）い所へ流（なが）れる。山にふった雨は、あつまって川になり、さらに低い所へ流れて、さいごには、いちばん低い所にある海へ流れこむから。\n\n【ステップ1】雨水は低い所へ流れる\n【ステップ2】低い所にあつまって川になる\n【ステップ3】川のおわりは、海\n\n【答え】海\n\n【たしかめ】地図で川をたどって、さいごにどこへ流れこんでいるかを見る。\n\n【よくあるまちがい】みずうみに流れこむと考えてしまう。大きな川は、さいごには海へ向（む）かう。", "difficulty": "standard", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b053", "subject": "rika", "question": "水が冷（ひ）えて、こおりはじめるのは、およそ何℃ですか。数字で書きましょう。", "answer": "0", "hint": "氷水（こおりみず）の温度（おんど）と、同じだよ。", "explanation": "【何を聞かれているか】水がこおりはじめる温度（おんど）。\n\n【なぜそうなるのか】水は、冷（ひ）やしていくと、0℃でこおりはじめる。氷（こおり）がまじった水の温度が0℃であることは、実験（じっけん）でも何度もたしかめられているから。\n\n【ステップ1】水を冷やしていく\n【ステップ2】こおりはじめたときの温度計を読む\n【ステップ3】およそ0℃\n\n【答え】0\n\n【たしかめ】氷水に温度計を入れて、読みが0℃近くになるか、実さいにたしかめる。\n\n【よくあるまちがい】10℃や5℃でこおると考えてしまう。水は、0℃でこおりはじめる。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b054", "subject": "rika", "question": "水がふっとうしているときの温度（おんど）は、ふつう、およそ何℃ですか。数字で書きましょう。", "answer": "100", "hint": "水がわき立つ、あつい温度（おんど）だよ。", "explanation": "【何を聞かれているか】水がふっとうする温度（おんど）。\n\n【なぜそうなるのか】水を熱（ねっ）していくと、およそ100℃で、水の中から大きなあわが出て、わき立つ。この温度を、ふっとう点といい、ふつうの空気のもとでは約（やく）100℃だから。\n\n【ステップ1】水を熱して、ふっとうさせる\n【ステップ2】わき立ったときの温度計を読む\n【ステップ3】およそ100℃\n\n【答え】100\n\n【たしかめ】ふっとうしている水の温度を、温度計ではかって、100℃近くであることをたしかめる。\n\n【よくあるまちがい】50℃や80℃でふっとうすると、考えてしまう。ふっとう点は、約100℃。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b055", "subject": "rika", "question": "水がこおって氷（こおり）になると、体積（たいせき）はどうなりますか。", "answer": "ふえる", "hint": "水を入れたふくろをこおらせると、ふくろがふくらむよ。", "explanation": "【何を聞かれているか】水がこおったときの体積（たいせき）。\n\n【なぜそうなるのか】水は、こおって氷（こおり）になると、体積がふえる。そのため、水を入れた入れものをこおらせると、ふえた体積で入れものがやぶれたり、ふくらんだりするから。\n\n【ステップ1】水を、入れものに入れてこおらせる\n【ステップ2】氷になると、体積がふえる\n【ステップ3】入れものの水面（すいめん）が、ふくらんで高くなる\n\n【答え】ふえる\n\n【たしかめ】水をはかっておいて、こおらせたあと、同じ入れものでの高さをくらべる。\n\n【よくあるまちがい】氷のほうが、冷（つめ）たいから小さくなると考えてしまう。水は、こおると体積がふえる。", "difficulty": "standard", "examType": "chugaku", "grade": "e4", "choices": ["へる", "ふえる", "変わらない"]},
  {"id": "grade_e4_rika_b056", "subject": "rika", "question": "水をふっとうさせつづけているとき、水の温度（おんど）は、どうなりますか。", "answer": "ほとんど変わらない", "hint": "わき立っている間は、熱（ねつ）が水のすがたを変（か）えるのに使（つか）われるよ。", "explanation": "【何を聞かれているか】ふっとう中の温度（おんど）。\n\n【なぜそうなるのか】ふっとうしている間は、加（くわ）えた熱（ねつ）が、水を水じょう気に変（か）えることに使（つか）われる。そのため、さらに熱しても、温度はおよそ100℃のまま、ほとんど変わらないから。\n\n【ステップ1】水が、ふっとうしている\n【ステップ2】さらに熱しつづける\n【ステップ3】温度は、ほとんど変わらない\n\n【答え】ほとんど変わらない\n\n【たしかめ】ふっとうしてから、1分ごとに温度計を読み、同じ数が続（つづ）くかを見る。\n\n【よくあるまちがい】熱しつづけると、どんどん温度が上がると考えてしまう。ふっとう中は変わらない。", "difficulty": "standard", "examType": "chugaku", "grade": "e4", "choices": ["どんどん上がる", "だんだん下がる", "ほとんど変わらない"]},
  {"id": "grade_e4_rika_b057", "subject": "rika", "question": "水がふっとうしているとき、水の中から出てくる、大きなあわは何ですか。ひらがなで書きましょう。", "answer": "すいじょうき", "hint": "水が、目に見えない気体に変（か）わったものだよ。", "explanation": "【何を聞かれているか】ふっとう中のあわの正体。\n\n【なぜそうなるのか】ふっとうでは、水の中から、水が気体になって出てくる。そのあわの正体は、水じょう気で、空気ではない。水がすがたを変（か）えたものだから。\n\n【ステップ1】ふっとう中の水を見る\n【ステップ2】水の中から、あわが出てくる\n【ステップ3】あわは水じょう気\n\n【答え】すいじょうき\n\n【たしかめ】ふっとうさせた水の量（りょう）が、だんだん少なくなっていくかを調（しら）べる。\n\n【よくあるまちがい】「空気」だと思ってしまう。あわは、水そのものが気体になったもの。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b058", "subject": "rika", "question": "やかんの口から出ている、白い湯気（ゆげ）は、何でできていますか。", "answer": "小さな水のつぶ", "hint": "見えているということは、気体ではないよ。", "explanation": "【何を聞かれているか】湯気（ゆげ）の正体。\n\n【なぜそうなるのか】水じょう気は目に見えない。やかんの口から出た水じょう気が、まわりの空気に冷（ひ）やされて、小さな水のつぶにもどったものが湯気で、目に見えるから。\n\n【ステップ1】水じょう気は、目に見えない\n【ステップ2】冷やされると、小さな水のつぶにもどる\n【ステップ3】見えている湯気は、水のつぶ\n\n【答え】小さな水のつぶ\n\n【たしかめ】やかんの口のすぐ近くは、見えないが、少しはなれると白く見えることをたしかめる。\n\n【よくあるまちがい】湯気を、水じょう気だと思ってしまう。見えるのは、水のつぶ。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["すがたの見えない水じょう気", "小さな水のつぶ", "氷のかたまり"]},
  {"id": "grade_e4_rika_b059", "subject": "rika", "question": "氷（こおり）がとけて、水に変（か）わっている間（氷が残（のこ）っている間）の温度（おんど）は、およそ何℃ですか。数字で書きましょう。", "answer": "0", "hint": "氷水（こおりみず）の温度（おんど）と、同じだよ。", "explanation": "【何を聞かれているか】氷（こおり）がとけている間の温度（おんど）。\n\n【なぜそうなるのか】氷があたためられても、氷がとけているあいだは、熱（ねつ）がとかすことに使（つか）われる。そのため、氷が残（のこ）っているあいだ、温度はおよそ0℃のまま変（か）わらないから。\n\n【ステップ1】氷を、あたためる\n【ステップ2】氷がとけているあいだは、熱がとかすことに使われる\n【ステップ3】温度は、およそ0℃のまま\n\n【答え】0\n\n【たしかめ】氷水の温度を、1分ごとにはかって、氷が残っているあいだは、同じ数であることを見る。\n\n【よくあるまちがい】氷がとけはじめたら、すぐに温度が上がると考えてしまう。氷が残っているあいだは0℃。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b060", "subject": "rika", "question": "水を熱（ねっ）したら、はじめは20℃で、2分ごとに16℃ずつ上がりました。6分たったときの温度（おんど）は何℃ですか。数字で書きましょう。", "answer": "68", "hint": "6分は、2分が何回分かを考えよう。", "explanation": "【何を聞かれているか】6分後の水の温度（おんど）。\n\n【なぜそうなるのか】2分ごとに16℃ずつ上がるので、6分では、2分が3回分になる。1回で16℃上がるのだから、3回分の上がり方をはじめの温度にたして、6分後の温度が分かるから。\n\n【ステップ1】6÷2＝3 で、2分が3回分\n【ステップ2】上がった分は、16×3＝48\n【ステップ3】はじめの20に48をたして、20＋48＝68\n\n【答え】68\n\n【たしかめ】20、36、52、68と、2分ごとに16たして、6分のところが68になるか見る。\n\n【よくあるまちがい】16×3の48を、そのまま答えにしてしまう。はじめの20℃をたすのをわすれない。", "difficulty": "standard", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b061", "subject": "rika", "question": "同じ大きさの入れものに、いっぱいの水と、いっぱいの空気を入れました。重（おも）いのは、どちらですか。", "answer": "水", "hint": "空気は、手に持（も）っても、重（おも）さをほとんど感（かん）じないよ。", "explanation": "【何を聞かれているか】水と空気の重（おも）さのくらべ。\n\n【なぜそうなるのか】同じ大きさの入れものでくらべると、水のほうが、空気よりもずっと重い。空気にも重さはあるが、水の重さにくらべると、とても軽（かる）いから。\n\n【ステップ1】入れものの大きさは、同じ\n【ステップ2】水は、ずっしりと重い\n【ステップ3】空気は、水にくらべてとても軽い\n\n【答え】水\n\n【たしかめ】同じ大きさのふくろに水と空気を入れて、手に持（も）ち、重さをくらべる。\n\n【よくあるまちがい】「空気には重さがない」と考えてしまう。空気にも重さはあるが、水よりずっと軽い。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["空気", "水", "同じ重さ"]},
  {"id": "grade_e4_rika_b062", "subject": "rika", "question": "空気をたくさん入れたボールは、入れる前より重（おも）くなりますか。「はい」か「いいえ」で答えましょう。", "answer": "はい", "hint": "空気にも、少しだけ重（おも）さがあるよ。", "explanation": "【何を聞かれているか】空気を入れたボールの重（おも）さ。\n\n【なぜそうなるのか】空気にも重さがあるので、ボールに空気をたくさん入れると、中の空気の重さの分だけ、ボール全体（ぜんたい）が少し重くなる。重さのちがいは、はかりを使（つか）うと分かるから。\n\n【ステップ1】空気にも、重さがある\n【ステップ2】ボールに空気を入れると、中の空気がふえる\n【ステップ3】ふえた空気の重さの分だけ、重くなる\n\n【答え】はい\n\n【たしかめ】空気の少ないボールと、たくさん入れたボールを、はかりで重さをくらべる。\n\n【よくあるまちがい】「空気には重さがない」と考えて、「いいえ」と答えてしまう。空気にも重さはある。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b063", "subject": "rika", "question": "水そうの水の中で、コップをさかさにして、そのまましずめても、コップの中に水が入りきらないのは、中に何があるからですか。漢字（かんじ）二字で書きましょう。", "answer": "空気", "hint": "目には見えないが、そこにあるものだよ。", "explanation": "【何を聞かれているか】コップの中にあって水を入れさせないもの。\n\n【なぜそうなるのか】コップの中には、はじめから、空気が入っている。さかさにしてしずめると、空気はにげ場がないので、その場所（ところ）に水が入ってこられない。そのため、コップの中に水が入りきらないから。\n\n【ステップ1】コップをさかさにして、水にしずめる\n【ステップ2】コップの中には、はじめから空気がある\n【ステップ3】空気がじゃまをして、水が入れない\n\n【答え】空気\n\n【たしかめ】コップをななめにかたむけると、あわが出て、水が入ることをたしかめる。\n\n【よくあるまちがい】「何も入っていない」と考えてしまう。からに見えても、空気が入っている。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b064", "subject": "rika", "question": "つつに入れた空気の長さが10cmでした。ピストンをおして、6cmになりました。空気の長さは、何cmちぢみましたか。数字で書きましょう。", "answer": "4", "hint": "はじめの長さから、あとの長さを引こう。", "explanation": "【何を聞かれているか】空気の長さのちがい。\n\n【なぜそうなるのか】空気は、おしちぢめることができる。おしたあとの長さは短（みじか）くなるので、ちぢんだ分は、はじめの長さから、あとの長さを引くと分かるから。\n\n【ステップ1】はじめは10cm、おしたあとは6cm\n【ステップ2】ちぢんだ分は、10から6を引く\n【ステップ3】10−6＝4\n\n【答え】4\n\n【たしかめ】6に4をたすと10になるか、たしかめる。\n\n【よくあるまちがい】10と6をたして16としてしまう。ちぢんだ分は、ちがいなので、引き算。", "difficulty": "standard", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b065", "subject": "rika", "question": "空気だけを入れた注（ちゅう）しゃ器（き）のピストンをおしこんで、手をはなすと、ピストンはどうなりますか。", "answer": "もとの位置にもどる", "hint": "おしちぢめられた空気は、もとの大きさにもどろうとするよ。", "explanation": "【何を聞かれているか】おしたあとのピストンの動（うご）き。\n\n【なぜそうなるのか】空気は、おしちぢめられると、もとの大きさにもどろうとするせいしつがある。そのため、手をはなすと、中の空気がピストンをおし返（かえ）して、もとの位置（いち）までもどってくるから。\n\n【ステップ1】ピストンをおして、空気をちぢめる\n【ステップ2】空気は、もとの大きさにもどろうとする\n【ステップ3】ピストンが、もとの位置にもどる\n\n【答え】もとの位置にもどる\n\n【たしかめ】手をはなして、ピストンがもとの目もりにもどるかを、見てたしかめる。\n\n【よくあるまちがい】「おしこんだまま動かない」と考えてしまう。空気は、もとにもどろうとする。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["おしこんだままになる", "さらにおくへすすむ", "もとの位置にもどる"]},
  {"id": "grade_e4_rika_b066", "subject": "rika", "question": "水の中で、ストローから空気をふきこむと、できたあわは、上と下のどちらに動（うご）きますか。漢字（かんじ）一字で書きましょう。", "answer": "上", "hint": "水のほうが重（おも）いので、軽（かる）い空気はおしあげられるよ。", "explanation": "【何を聞かれているか】あわの動（うご）く向（む）き。\n\n【なぜそうなるのか】同じ大きさでくらべると、水のほうが空気より重（おも）い。そのため、水の中に出た空気のあわは、まわりの水におしあげられて、水面（すいめん）へのぼっていくから。\n\n【ステップ1】水の中に、空気のあわを出す\n【ステップ2】水は、空気より重い\n【ステップ3】あわは、上へのぼる\n\n【答え】上\n\n【たしかめ】水そうの水の中で、ストローから息（いき）をふいて、あわが水面へ向かうのを見る。\n\n【よくあるまちがい】空気も重さがあるから、下にしずむと考えてしまう。水より軽（かる）いので、あわは上へ行く。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b067", "subject": "rika", "question": "空気だけを入れて先をふさいだ注（ちゅう）しゃ器（き）の、ピストンを引くと、中の空気の体積（たいせき）はどうなりますか。", "answer": "大きくなる", "hint": "空気は、広いところに出ると、広がるよ。", "explanation": "【何を聞かれているか】ピストンを引いたときの空気の体積（たいせき）。\n\n【なぜそうなるのか】先がふさがっているので、空気は外へ出られない。ピストンを引くと、つつの中が広くなり、空気がその広さいっぱいに広がるので、体積が大きくなるから。\n\n【ステップ1】先がふさがれていて、空気は出られない\n【ステップ2】ピストンを引くと、中が広くなる\n【ステップ3】空気が広がって、体積が大きくなる\n\n【答え】大きくなる\n\n【たしかめ】引いた手をはなすと、ピストンがもとにもどることも、たしかめてみる。\n\n【よくあるまちがい】「おしたときと同じで、小さくなる」と考えてしまう。引くと、空気は広がる。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["小さくなる", "大きくなる", "変わらない"]},
  {"id": "grade_e4_rika_b068", "subject": "rika", "question": "つつに入れた空気の長さが12cmでした。ピストンをおして、はじめの半分の長さにしました。空気の長さは、何cmになりましたか。数字で書きましょう。", "answer": "6", "hint": "半分は、2でわった数だよ。", "explanation": "【何を聞かれているか】半分の長さ。\n\n【なぜそうなるのか】空気は、おしちぢめることができる。半分の長さにするので、はじめの長さを2でわった数が、おしたあとの長さになるから。\n\n【ステップ1】はじめは12cm\n【ステップ2】半分にするので、12を2でわる\n【ステップ3】12÷2＝6\n\n【答え】6\n\n【たしかめ】6を2回たすと12になるか、たしかめる。\n\n【よくあるまちがい】12−2＝10と、引き算にしてしまう。半分にするときは、2でわる。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b069", "subject": "rika", "question": "金ぞくのぼうのはしを熱（ねっ）したとき、熱は、どのように伝（つた）わりますか。", "answer": "熱した所から、順に遠くへ伝わる", "hint": "ぼうにろうをぬっておくと、とけていく順（じゅん）番で分かるよ。", "explanation": "【何を聞かれているか】金ぞくのあたたまり方。\n\n【なぜそうなるのか】金ぞくは、熱（ねっ）せられた部（ぶ）分から、となりへ、となりへと順（じゅん）に熱を伝（つた）えていく。そのため、熱した所（ところ）に近いところから順にあたたまっていくから。\n\n【ステップ1】ぼうのはしを熱する\n【ステップ2】熱が、となりの部分へ伝わる\n【ステップ3】熱した所に近いところから、順にあたたまる\n\n【答え】熱した所から、順に遠くへ伝わる\n\n【たしかめ】ぼうにぬったろうが、熱した所に近い順にとけていくかを、見てたしかめる。\n\n【よくあるまちがい】「全体（ぜんたい）が一度（ど）にあたたまる」と考えてしまう。順番に伝わっていく。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["熱した所から、順に遠くへ伝わる", "熱した所と遠い所が先にあたたまる", "一度に全体があたたまる"]},
  {"id": "grade_e4_rika_b070", "subject": "rika", "question": "まるい金ぞくの板（いた）のまん中を熱（ねっ）すると、熱は、まん中からどんな形に広がっていきますか。漢字（かんじ）一字で書きましょう。", "answer": "円", "hint": "石を水に落（お）としたときの、水の広がり方と同じ形だよ。", "explanation": "【何を聞かれているか】熱（ねつ）の広がる形。\n\n【なぜそうなるのか】金ぞくの板（いた）は、熱せられた部（ぶ）分から、まわりへ順（じゅん）に熱を伝（つた）える。まん中から、まわりのどの方向（ほうこう）にも同じ速（はや）さで伝わるので、熱は、同じ円の形で広がっていくから。\n\n【ステップ1】まん中を熱する\n【ステップ2】熱が、まわりのどの方向にも同じように伝わる\n【ステップ3】熱の広がりは、円の形\n\n【答え】円\n\n【たしかめ】板にろうをぬっておくと、まん中から円形にとけていくかを、見てたしかめる。\n\n【よくあるまちがい】一方向にだけ広がると考えてしまう。まん中から、まわり全体（ぜんたい）に広がる。", "difficulty": "standard", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b071", "subject": "rika", "question": "試験管（しけんかん）に入れた水を、早く全体（ぜんたい）あたためるには、下の方と上の方のどちらを熱（ねっ）するのがよいですか。漢字（かんじ）一字で書きましょう。", "answer": "下", "hint": "あたためられた水は、うごいて全体（ぜんたい）にまわるよ。", "explanation": "【何を聞かれているか】水をあたためるときの、熱（ねっ）する場所（ところ）。\n\n【なぜそうなるのか】水は、あたためられると上へ動（うご）き、上にあった冷（つめ）たい水が下へ動く。下を熱すると、この動きで水全体（ぜんたい）がかき回されて、早くあたたまる。上を熱すると、あたためられた水は上にとどまってしまい、下まで熱が伝（つた）わりにくいから。\n\n【ステップ1】あたためられた水は上へ動く\n【ステップ2】下を熱すると、水がぐるぐる動く\n【ステップ3】水全体が、早くあたたまる\n\n【答え】下\n\n【たしかめ】試験管（しけんかん）の下と上を別々（べつべつ）に熱して、全体があたたまる早さを見くらべる。\n\n【よくあるまちがい】金ぞくと同じで、熱したところだけがあたたまると考えてしまう。水は、動いて全体をあたためる。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b072", "subject": "rika", "question": "水をあたためたとき、あたためられた水は、上と下のどちらへ動（うご）きますか。漢字（かんじ）一字で書きましょう。", "answer": "上", "hint": "おがくずを入れると、動（うご）きが見えるよ。", "explanation": "【何を聞かれているか】あたためられた水の動（うご）く向（む）き。\n\n【なぜそうなるのか】あたためられた水は、まわりの冷（つめ）たい水より軽（かる）くなるので、上へ動く。そのあとに、冷たい水が下へ動き、ぐるぐると動いて全体（ぜんたい）があたたまるから。\n\n【ステップ1】ビーカーの水の下をあたためる\n【ステップ2】あたためられた水は軽くなる\n【ステップ3】軽くなった水は、上へ動く\n\n【答え】上\n\n【たしかめ】水におがくずを入れて、あたためたときの動きを見て、上へ向かうのをたしかめる。\n\n【よくあるまちがい】重（おも）くなって、下に動くと考えてしまう。あたたまった水は上へ行く。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b073", "subject": "rika", "question": "ストーブで、部屋（へや）の空気をあたためたとき、気温（きおん）が高くなるのは、どの辺（あた）りですか。", "answer": "てんじょうの近く", "hint": "あたたかい空気は、軽（かる）くなって、動（うご）くよ。", "explanation": "【何を聞かれているか】部屋（へや）の中で、気温（きおん）が高い場所（ところ）。\n\n【なぜそうなるのか】あたためられた空気は、軽（かる）くなって上へ動（うご）くので、部屋の上のほう、つまり、てんじょうの近くにあつまる。ゆかの近くには、冷（つめ）たい空気が残（のこ）りやすいから。\n\n【ステップ1】空気も、あたためられると軽くなる\n【ステップ2】軽くなった空気は、上へ動く\n【ステップ3】てんじょうの近くが、高くなる\n\n【答え】てんじょうの近く\n\n【たしかめ】高い所と低（ひく）い所に温度計（おんどけい）をおいて、温度の読みをくらべてたしかめる。\n\n【よくあるまちがい】「ゆかの近くが、あたたかい」と考えてしまう。あたたかい空気は上へ行く。", "difficulty": "standard", "examType": "chugaku", "grade": "e4", "choices": ["ゆかの近く", "てんじょうの近く", "どこも同じ"]},
  {"id": "grade_e4_rika_b074", "subject": "rika", "question": "あたたかい空気と冷（つめ）たい空気では、冷たい空気は、上と下のどちらに集（あつ）まりますか。漢字（かんじ）一字で書きましょう。", "answer": "下", "hint": "あたたかい空気は上に行くよ。", "explanation": "【何を聞かれているか】冷（つめ）たい空気がたまる向（む）き。\n\n【なぜそうなるのか】あたたかい空気は軽（かる）くて上へ、冷たい空気は重（おも）くて下へ動（うご）く。そのため、冷たい空気は、下の方に集（あつ）まりやすいから。\n\n【ステップ1】あたたかい空気は軽く、上へ行く\n【ステップ2】冷たい空気は、あたたかい空気より重い\n【ステップ3】冷たい空気は、下に集まる\n\n【答え】下\n\n【たしかめ】部屋（へや）の高い所（ところ）と低（ひく）い所の温度（おんど）をくらべて、低い所が冷たいかをたしかめる。\n\n【よくあるまちがい】「冷たい空気は、軽いので上に行く」と考えてしまう。冷たい空気は重くて下にたまる。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b075", "subject": "rika", "question": "金ぞく・水・空気のうち、熱（ねっ）した所（ところ）から、となりへ順（じゅん）に熱が伝（つた）わって、あたたまるものは、どれですか。", "answer": "金ぞく", "hint": "動（うご）いて全体（ぜんたい）をあたためるのは、水と空気だよ。", "explanation": "【何を聞かれているか】熱（ねつ）が順（じゅん）に伝（つた）わるもの。\n\n【なぜそうなるのか】金ぞくは、物（もの）が動（うご）かない。そのため、熱した所（ところ）のとなりへ、となりへと順に熱が伝わっていく。水と空気は、あたたまったものが動くことで、全体（ぜんたい）があたたまるから。\n\n【ステップ1】金ぞくは、動かないで熱が伝わる\n【ステップ2】水と空気は、動いて全体があたたまる\n【ステップ3】順に伝わるのは、金ぞく\n\n【答え】金ぞく\n\n【たしかめ】金ぞくのぼうにろうをぬって、熱した所に近い順にとけるかをたしかめる。\n\n【よくあるまちがい】水や空気も、順に熱が伝わると考えてしまう。水と空気は、動いてあたたまる。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["金ぞく", "水", "空気"]},
  {"id": "grade_e4_rika_b076", "subject": "rika", "question": "金ぞくのぼうを、はしから熱（ねっ）しました。熱した所（ところ）から5cm・10cm・15cmの所にろうをぬっておくと、いちばん最後（さいご）にとけるのは、何cmの所ですか。数字で書きましょう。", "answer": "15", "hint": "熱（ねっ）した所（ところ）から遠いほど、あたたまるのは後になるよ。", "explanation": "【何を聞かれているか】最後（さいご）にとけるろうの位置（いち）。\n\n【なぜそうなるのか】金ぞくは、熱（ねっ）した所（ところ）から近い順（じゅん）に、熱が伝（つた）わっていく。いちばん遠い所は、いちばん最後にあたたまるので、いちばん遠い15cmの所のろうが、最後にとけるから。\n\n【ステップ1】熱は、近い所から順に伝わる\n【ステップ2】5cm、10cm、15cmの順に、あたたまる\n【ステップ3】最後にとけるのは、いちばん遠い15cm\n\n【答え】15\n\n【たしかめ】とける順番が、5cm、10cm、15cmの順になるか、ろうを使（つか）って見る。\n\n【よくあるまちがい】5cmの所が最後だと考えてしまう。熱した所に近いほど、先にとける。", "difficulty": "standard", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b077", "subject": "rika", "question": "モーターにつないだ、かん電池の向（む）きを反対（はんたい）にすると、モーターの回る向きは、どうなりますか。", "answer": "反対になる", "hint": "電気が流（なが）れる向（む）きが、どうなるかを考えよう。", "explanation": "【何を聞かれているか】電池の向（む）きと、モーターの回る向き。\n\n【なぜそうなるのか】モーターは、電気が流（なが）れる向きによって、回る向きが決（き）まる。電池の向きを反対（はんたい）にすると、電気の流れる向きが反対になるので、モーターの回る向きも反対になるから。\n\n【ステップ1】電池の向きを、反対にする\n【ステップ2】電気の流れる向きが、反対になる\n【ステップ3】モーターの回る向きも、反対になる\n\n【答え】反対になる\n\n【たしかめ】電池の向きを元にもどすと、モーターも元の向きに回るかを、たしかめる。\n\n【よくあるまちがい】「止まる」と考えてしまう。向きを反対にしても電気は流れるので、反対向きに回る。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["変わらない", "止まる", "反対になる"]},
  {"id": "grade_e4_rika_b078", "subject": "rika", "question": "かん電池を直列（ちょくれつ）につなぐ数をふやして、モーターが1分間に回った回数をはかりました。1こは20回、2こは35回、3こは50回でした。いちばんはやく回ったのは、かん電池を何こつないだときですか。数字で書きましょう。", "answer": "3", "hint": "回数の数字が、いちばん大きいものをさがそう。", "explanation": "【何を聞かれているか】いちばんはやく回ったときの電池の数。\n\n【なぜそうなるのか】回った回数が多いほど、モーターははやく回っている。表（ひょう）を見ると、回数がいちばん多いのは50回で、そのときのかん電池は3こだから。直列（ちょくれつ）につなぐ電池の数がふえるほど、モーターははやく回る。\n\n【ステップ1】電池1こは20回、2こは35回、3こは50回\n【ステップ2】回数の大きい順（じゅん）は、50回、35回、20回\n【ステップ3】50回のときの、電池は3こ\n\n【答え】3\n\n【たしかめ】電池の数がふえるたびに、回数もふえているか、表を左から右へ見る。\n\n【よくあるまちがい】「電池が少ないほうがはやい」と考えてしまう。直列では、電池が多いほど、はやく回る。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b079", "subject": "rika", "question": "光を当てると、電気をつくる電池を、何といいますか。漢字（かんじ）三字で書きましょう。", "answer": "光電池", "hint": "電たくの上に、ついていることがあるよ。", "explanation": "【何を聞かれているか】光で電気をつくる電池の名前。\n\n【なぜそうなるのか】光電池は、光が当たると、電気をつくることができる。かん電池のように、つかうと中のものがへっていく電池ではなく、光が当たっている間、電気をつくりつづけられるから。\n\n【ステップ1】光が当たると、電気ができる電池をさがす\n【ステップ2】ソーラーでんたくにも使（つか）われている\n【ステップ3】その電池は、光電池\n\n【答え】光電池\n\n【たしかめ】光電池にモーターをつないで、明るい所（ところ）に出すと、モーターが回るかをたしかめる。\n\n【よくあるまちがい】かん電池と同じと考えてしまう。光電池は、光が当たっているときだけ電気をつくる。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b080", "subject": "rika", "question": "かん電池の＋きょくと、となりの電池の−きょくを、つないでいくつなぎ方を、何といいますか。漢字（かんじ）二字で書きましょう。", "answer": "直列", "hint": "ひとつながりの「れつ」をつくるつなぎ方だよ。", "explanation": "【何を聞かれているか】電池のつなぎ方の名前。\n\n【なぜそうなるのか】電池を、一列（れつ）にならべて、＋きょくと−きょくを、順（じゅん）につないでいくつなぎ方を、直列つなぎという。直列につなぐと、電池の数がふえるぶん、電気を流（なが）すはたらきが大きくなるから。\n\n【ステップ1】電池を、一列にならべる\n【ステップ2】＋とつぎの−を、つないでいく\n【ステップ3】そのつなぎ方を、直列という\n\n【答え】直列\n\n【たしかめ】電池を2こ直列につなぐと、モーターが1このときより、はやく回るかを見る。\n\n【よくあるまちがい】＋どうし、−どうしをつなぐと思ってしまう。直列は、＋と−をつなぐ。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b081", "subject": "rika", "question": "豆電球（まめでんきゅう）のガラスの中にある、細い線が切れていると、豆電球は、つきますか。「はい」か「いいえ」で答えましょう。", "answer": "いいえ", "hint": "そこは、電気の通り道の一部（ぶ）になっているよ。", "explanation": "【何を聞かれているか】切れた豆電球（まめでんきゅう）のようす。\n\n【なぜそうなるのか】豆電球の中の細い線に電気が流（なが）れて、光と熱（ねつ）が出ている。この線が切れてしまうと、電気の通り道が切れて、豆電球は、つかなくなるから。\n\n【ステップ1】豆電球の中の、細い線を見る\n【ステップ2】この線も、電気の通り道の一部（ぶ）\n【ステップ3】切れると、電気が流れず、つかない\n\n【答え】いいえ\n\n【たしかめ】切れていない豆電球につなぎかえて、つくかどうかをたしかめる。\n\n【よくあるまちがい】電池が切れたと、考えてしまう。切れた線のせいで、つかないことがある。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b082", "subject": "rika", "question": "光電池に当てる光を強くすると、モーターの回り方は、どうなりますか。", "answer": "はやくなる", "hint": "光が強いほど、電気をたくさんつくるよ。", "explanation": "【何を聞かれているか】光の強さと、モーターの回り方。\n\n【なぜそうなるのか】光電池は、当たる光が強いほど、たくさんの電気をつくる。電気が多く流（なが）れると、モーターははやく回るから。\n\n【ステップ1】光を強く当てる\n【ステップ2】光電池が、電気を多くつくる\n【ステップ3】モーターが、はやく回る\n\n【答え】はやくなる\n\n【たしかめ】光を強くしたり、弱くしたりして、モーターの回り方を見くらべる。\n\n【よくあるまちがい】光の強さと、回り方は、関係（かんけい）がないと考えてしまう。光が強いほど、はやくなる。", "difficulty": "standard", "examType": "chugaku", "grade": "e4", "choices": ["おそくなる", "はやくなる", "変わらない"]},
  {"id": "grade_e4_rika_b083", "subject": "rika", "question": "光電池の＋きょくと−きょくを、反対（はんたい）にして、モーターにつなぎかえました。モーターの回る向（む）きは、どうなりますか。", "answer": "反対になる", "hint": "電池の向（む）きを反対（はんたい）にしたときと、同じだよ。", "explanation": "【何を聞かれているか】光電池の向（む）きと、モーターの回る向き。\n\n【なぜそうなるのか】光電池も、電気の流（なが）れる向きが決（き）まっている。つなぎ方を反対（はんたい）にすると、電気の流れる向きが反対になり、モーターの回る向きも反対になるから。\n\n【ステップ1】光電池の＋と−を、反対につなぐ\n【ステップ2】電気の流れる向きが、反対になる\n【ステップ3】モーターの回る向きも、反対になる\n\n【答え】反対になる\n\n【たしかめ】つなぎ方を元にもどして、モーターが元の向きに回るかを見る。\n\n【よくあるまちがい】「止まる」と考えてしまう。つなぎかえても、電気は流れるので、反対向きに回る。", "difficulty": "standard", "examType": "chugaku", "grade": "e4", "choices": ["変わらない", "止まる", "反対になる"]},
  {"id": "grade_e4_rika_b084", "subject": "rika", "question": "かん電池を直列（ちょくれつ）につなぐ数をふやして、モーターが1分間に回った回数をはかりました。1こは20回、2こは35回、3こは50回でした。3このときは、1このときより、何回多く回りましたか。数字で書きましょう。", "answer": "30", "hint": "大きいほうから、小さいほうを引こう。", "explanation": "【何を聞かれているか】3このときと1このときの、回数のちがい。\n\n【なぜそうなるのか】回った回数のちがいは、多いほうから少ないほうを引くと分かる。3このときの50回から、1このときの20回を引くから。\n\n【ステップ1】3こは50回、1こは20回\n【ステップ2】ちがいは、50から20を引く\n【ステップ3】50−20＝30\n\n【答え】30\n\n【たしかめ】20に30をたすと50になるか、たしかめる。\n\n【よくあるまちがい】35回を使（つか）ってしまう。聞かれているのは、3こと1この、ちがい。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b085", "subject": "rika", "question": "夕方に、西の空にひくく見える、細い月の形は、どれですか。", "answer": "三日月", "hint": "細くて、弓のような形をした月だよ。", "explanation": "【何を聞かれているか】夕方の西の空に見える月。\n\n【なぜそうなるのか】三日月は、月の細いところだけが光って見える形で、太陽（たいよう）がしずんだあとの夕方に、西の空にひくく見える。そのあと、すぐに月もしずむので、夜おそくには見られないから。\n\n【ステップ1】夕方の西の空を見る\n【ステップ2】細い月が、太陽のしずんだ方に見える\n【ステップ3】その形は、三日月\n\n【答え】三日月\n\n【たしかめ】三日月が夕方に西の空に見えることを、月の記録（きろく）を見て、たしかめる。\n\n【よくあるまちがい】満月（まんげつ）が夕方西に見えると考えてしまう。満月は、夕方東からのぼる。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["満月", "三日月", "半月"]},
  {"id": "grade_e4_rika_b086", "subject": "rika", "question": "夕方に、東の空からのぼってくる月の形は、どれですか。", "answer": "満月", "hint": "まるい形をした月だよ。", "explanation": "【何を聞かれているか】夕方の東の空に見える月。\n\n【なぜそうなるのか】満月（まんげつ）は、日がしずむころに東からのぼり、ひとばんかけて空を動（うご）いて、朝方に西にしずむ。そのため、夕方に東の空に見えるのは、まるい満月だから。\n\n【ステップ1】夕方の東の空を見る\n【ステップ2】のぼってくる月を見る\n【ステップ3】まるい月は、満月\n\n【答え】満月\n\n【たしかめ】満月の日の夕方に、東の空を見て、まるい月がのぼってくるのを見る。\n\n【よくあるまちがい】三日月を東の空に見ると、考えてしまう。三日月は、西の空に見える。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["三日月", "新月", "満月"]},
  {"id": "grade_e4_rika_b087", "subject": "rika", "question": "夕方、南の空に見える、半分だけ光っている月の形を何といいますか。漢字（かんじ）二字で書きましょう。", "answer": "半月", "hint": "右半分が光った形で、円の半分に見えるよ。", "explanation": "【何を聞かれているか】夕方の南の空に見える月。\n\n【なぜそうなるのか】半月は、円の半分だけが光って見える月で、夕方に南の空に見える。そのあと、夜のうちに、西の空へ動（うご）いてしずむから。\n\n【ステップ1】夕方の南の空を見る\n【ステップ2】半分だけ光っている月がある\n【ステップ3】半分の月だから「半月」\n\n【答え】半月\n\n【たしかめ】月の形をスケッチして、半分の形になっているかを、見てたしかめる。\n\n【よくあるまちがい】三日月や満月（まんげつ）と、まちがえてしまう。半分に見えるのが半月。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b088", "subject": "rika", "question": "オリオンざの「ベテルギウス」は、何色っぽく見える星ですか。漢字（かんじ）一字で書きましょう。", "answer": "赤", "hint": "トマトやりんごの、色と同じ色だよ。", "explanation": "【何を聞かれているか】ベテルギウスの色。\n\n【なぜそうなるのか】星は、明るさだけでなく、色もちがう。冬の夜空に見えるオリオンざの左上にある、ベテルギウスは、赤っぽい色に光って見えるから。\n\n【ステップ1】冬のオリオンざを思い出す\n【ステップ2】左上の明るい星が、ベテルギウス\n【ステップ3】ベテルギウスは、赤っぽい色\n\n【答え】赤\n\n【たしかめ】冬の夜空で、オリオンざの左上の星が、赤っぽく見えるかをたしかめる。\n\n【よくあるまちがい】白っぽい星と、まちがえてしまう。ベテルギウスは、赤っぽい。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b089", "subject": "rika", "question": "夏の大三角をつくる3つの星のうち、「わしざ」の星は、どれですか。", "answer": "アルタイル", "hint": "「わし」の名前がついたせいざにある星だよ。", "explanation": "【何を聞かれているか】わしざにある、夏の大三角の星。\n\n【なぜそうなるのか】夏の大三角は、ことざのベガ、わしざのアルタイル、はくちょうざのデネブの、3つの星をむすんでできる。そのうち、わしざにあるのは、アルタイルだから。\n\n【ステップ1】夏の大三角をつくる星の名前を思い出す\n【ステップ2】ベガは、ことざ。デネブは、はくちょうざ\n【ステップ3】わしざの星は、アルタイル\n\n【答え】アルタイル\n\n【たしかめ】星の名前とせいざを、せいざ早見で、ならべてたしかめる。\n\n【よくあるまちがい】ベガと、まちがえてしまう。ベガは、ことざの星。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["ベガ", "デネブ", "アルタイル"]},
  {"id": "grade_e4_rika_b090", "subject": "rika", "question": "オリオンざの星のならび方は、時間がたつと変（か）わりますか。「はい」か「いいえ」で答えましょう。", "answer": "いいえ", "hint": "せいざの形は、ずっと同じだよ。", "explanation": "【何を聞かれているか】せいざの形の変（か）わり方。\n\n【なぜそうなるのか】星は、時間がたつと、空をいっしょに動（うご）いて見える。星どうしの位置（いち）は、変わらないので、オリオンざの形もそのままで、ならび方は変わらないから。\n\n【ステップ1】せいざは、星をむすんでつくった形\n【ステップ2】時間がたつと、すべての星がいっしょに動く\n【ステップ3】星どうしの位置は変わらず、形は同じ\n\n【答え】いいえ\n\n【たしかめ】1時間おきにオリオンざをスケッチして、形が同じであることを見る。\n\n【よくあるまちがい】時間とともに、せいざの形がくずれると考えてしまう。形は同じで、空の位置が動く。", "difficulty": "standard", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b091", "subject": "rika", "question": "冬の大三角にふくまれる、おおいぬざの星で、青白く光る、夜空でいちばん明るい星は何ですか。カタカナで書きましょう。", "answer": "シリウス", "hint": "「おおいぬ」の目にあたる星だよ。", "explanation": "【何を聞かれているか】おおいぬざの、いちばん明るい星。\n\n【なぜそうなるのか】シリウスは、おおいぬざにある星で、青白い色に光る。夜空に見える星のなかで、いちばん明るい星で、冬の大三角のひとつだから。\n\n【ステップ1】冬の大三角をつくる星を思い出す\n【ステップ2】おおいぬざの星をさがす\n【ステップ3】おおいぬざのいちばん明るい星が、シリウス\n\n【答え】シリウス\n\n【たしかめ】冬の夜空で、青白く光るいちばん明るい星をさがして、せいざ早見でたしかめる。\n\n【よくあるまちがい】ベテルギウスと、まちがえてしまう。ベテルギウスは赤っぽく、シリウスは青白い。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b092", "subject": "rika", "question": "星をいくつか線でつないで、動物（どうぶつ）やものの形にみたてたものを、何といいますか。ひらがなで書きましょう。", "answer": "せいざ", "hint": "オリオンやさそりなどが、これにあたるよ。", "explanation": "【何を聞かれているか】星をつないだものの名前。\n\n【なぜそうなるのか】昔（むかし）の人は、夜空の星をつないで、動物（どうぶつ）やものの形にみたてて、名前をつけた。星をつないだこの形を、せいざという。せいざを使（つか）うと、星のある場所（ところ）を、見つけやすくなるから。\n\n【ステップ1】夜空の星を、つなぐ\n【ステップ2】動物やものの形にみたてる\n【ステップ3】このなまえが「せいざ」\n\n【答え】せいざ\n\n【たしかめ】せいざ早見で、いろいろなせいざの形を見て、たしかめる。\n\n【よくあるまちがい】「星ぞら」と、まちがえてしまう。星をつないだ形が、せいざ。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b093", "subject": "rika", "question": "ほねを持（も）っているのは、どれですか。", "answer": "ウサギ", "hint": "体を、ほねでささえているのは、人と同じなかまだよ。", "explanation": "【何を聞かれているか】ほねのある動物（どうぶつ）。\n\n【なぜそうなるのか】ウサギは、人と同じように、体の中にほねがあって、体をささえている。クラゲやミミズには、ほねがなく、やわらかい体をしているから。\n\n【ステップ1】人と同じように、ほねがあるのは、どれかを考える\n【ステップ2】クラゲとミミズは、やわらかい体で、ほねがない\n【ステップ3】ウサギには、ほねがある\n\n【答え】ウサギ\n\n【たしかめ】図かんで、ウサギのほねのつくりを見て、人とくらべる。\n\n【よくあるまちがい】ミミズにも、ほねがあると考えてしまう。ミミズには、ほねがない。", "difficulty": "basic", "examType": "chugaku", "grade": "e4", "choices": ["ウサギ", "クラゲ", "ミミズ"]},
  {"id": "grade_e4_rika_b094", "subject": "rika", "question": "うでのまん中あたりで、曲（ま）がるところを、何といいますか。ひらがなで書きましょう。", "answer": "ひじ", "hint": "うでを曲（ま）げると、角ができるところだよ。", "explanation": "【何を聞かれているか】うでのまん中の関節（かんせつ）。\n\n【なぜそうなるのか】うでには、ほねとほねのつなぎ目である関節があり、まん中あたりにあるのが、ひじ。ひじの関節があるから、うでを曲（ま）げたり、のばしたりできるから。\n\n【ステップ1】うでを曲げてみる\n【ステップ2】曲がるのは、うでのまん中あたり\n【ステップ3】そこが「ひじ」\n\n【答え】ひじ\n\n【たしかめ】自分のうでを曲げて、曲がるところがひじであることを、たしかめる。\n\n【よくあるまちがい】手首やかたと、まちがえてしまう。うでのまん中で曲がるのがひじ。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b095", "subject": "rika", "question": "足のまん中あたりで、曲（ま）がるところを、何といいますか。ひらがなで書きましょう。", "answer": "ひざ", "hint": "足を曲（ま）げると、角ができるところだよ。", "explanation": "【何を聞かれているか】足のまん中の関節（かんせつ）。\n\n【なぜそうなるのか】足にも、うでと同じように、ほねとほねのつなぎ目である関節がある。足のまん中あたりにあるのが、ひざで、ひざの関節があるから、足を曲（ま）げたり、のばしたりできるから。\n\n【ステップ1】足を曲げてみる\n【ステップ2】曲がるのは、足のまん中あたり\n【ステップ3】そこが「ひざ」\n\n【答え】ひざ\n\n【たしかめ】自分の足を曲げて、曲がるところがひざであることを、たしかめる。\n\n【よくあるまちがい】足首と、まちがえてしまう。足のまん中で曲がるのがひざ。", "difficulty": "standard", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b096", "subject": "rika", "question": "手とうでのつなぎ目で、曲（ま）がる関節（かんせつ）を、何といいますか。漢字（かんじ）二字で書きましょう。", "answer": "手首", "hint": "うでと手のあいだにあるよ。", "explanation": "【何を聞かれているか】手とうでをつなぐ関節（かんせつ）。\n\n【なぜそうなるのか】手とうでのつなぎ目には、関節があり、そこを手首という。手首の関節があるから、手を上下左右に動（うご）かすことができるから。\n\n【ステップ1】うでの先に、手がある\n【ステップ2】そのつなぎ目で、手を動かせる\n【ステップ3】つなぎ目は「手首」\n\n【答え】手首\n\n【たしかめ】自分の手を動かして、手首が曲（ま）がるかをたしかめる。\n\n【よくあるまちがい】ひじやかたと、まちがえてしまう。手とうでの間は、手首。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b097", "subject": "rika", "question": "氷（こおり）を水に変（か）えるには、あたためますか、冷（ひ）やしますか。ひらがなで書きましょう。", "answer": "あたためる", "hint": "氷（こおり）は、あたたかい部屋（へや）に置（お）いておくと、とけるよ。", "explanation": "【何を聞かれているか】氷（こおり）を水にするほうほう。\n\n【なぜそうなるのか】氷は、あたためられると、とけて水になる。氷の温度（おんど）が0℃になって、さらに熱（ねつ）が加（くわ）わると、すがたが氷から水へ変（か）わるから。反対（はんたい）に、水を冷（ひ）やすと、氷になる。\n\n【ステップ1】氷から水にしたい\n【ステップ2】氷は、あたためられるととける\n【ステップ3】あたためる\n\n【答え】あたためる\n\n【たしかめ】氷を手の上にのせると、手の熱でとけて水になることをたしかめる。\n\n【よくあるまちがい】「冷やすととける」と考えてしまう。氷は、あたためるととける。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b098", "subject": "rika", "question": "ある年の、夏は30℃、冬は5℃でした。夏は冬より、何℃高いですか。数字で書きましょう。", "answer": "25", "hint": "大きい数から、小さい数を引こう。", "explanation": "【何を聞かれているか】夏と冬の気温（きおん）のちがい。\n\n【なぜそうなるのか】夏は日光がよく当たり、気温が高い。冬は日光が弱く、気温がひくい。ちがいは、高いほうからひくいほうを引くと分かるから。\n\n【ステップ1】夏は30℃、冬は5℃\n【ステップ2】ちがいは、30から5を引く\n【ステップ3】30−5＝25\n\n【答え】25\n\n【たしかめ】5に25をたすと30になるか、たし算でたしかめる。\n\n【よくあるまちがい】30と5をたして35としてしまう。ちがいは、引き算。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b099", "subject": "rika", "question": "月は、新月から満月（まんげつ）まで、およそ何日かかりますか。数字で書きましょう。", "answer": "15", "hint": "月の形がもとにもどるまでの、半分くらいだよ。", "explanation": "【何を聞かれているか】新月から満月（まんげつ）までの日数。\n\n【なぜそうなるのか】月は、およそ1か月（約（やく）30日）で、もとの形にもどる。そのうち、新月から満月になるまでには、半分の、およそ15日かかるから。\n\n【ステップ1】月の形がもとにもどるまでは、約30日\n【ステップ2】新月から満月までは、その半分\n【ステップ3】30÷2＝15\n\n【答え】15\n\n【たしかめ】月の形の記録（きろく）で、新月から満月まで、日数をかぞえてみる。\n\n【よくあるまちがい】30日だと思ってしまう。30日は、もとの形にもどるまでの日数。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
  {"id": "grade_e4_rika_b100", "subject": "rika", "question": "ある年の、4月は15℃、8月は28℃、10月は17℃、1月は4℃でした。気温（きおん）がいちばん高いのは、何月ですか。数字で書きましょう。", "answer": "8", "hint": "4つの数のうち、いちばん大きいものをさがそう。", "explanation": "【何を聞かれているか】気温（きおん）がいちばん高い月。\n\n【なぜそうなるのか】気温の数が大きいほど、あたたかい。4つの数を見くらべると、28℃がいちばん大きく、それは8月だから。夏が、気温の高い季節（きせつ）であることとも合う。\n\n【ステップ1】4月は15℃、8月は28℃、10月は17℃、1月は4℃\n【ステップ2】数の大きいものをさがすと、28℃\n【ステップ3】28℃は、8月\n\n【答え】8\n\n【たしかめ】夏は気温が高いという、季節の特（とく）ちょうと、合っているか、見直す。\n\n【よくあるまちがい】数が小さいものを選（えら）んでしまう。いちばん高いのは、いちばん大きい数。", "difficulty": "basic", "examType": "chugaku", "grade": "e4"},
];
